INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0001', 'spa', 'Alfa; primera letra del alfabeto griego, usada como título divino que significa ''el Primero'' o ''el Principio''', 'Alfa es la primera letra del alfabeto griego, empleada en Apocalipsis como majestuosa autodesignación de Dios y del Cristo resucitado. En la frase «Yo soy el Alfa y la Omega», proclama primacía absoluta: aquel que se sitúa en el origen de todas las cosas. Las cuatro apariciones se encuentran en Apocalipsis (1:8, 11; 21:6; 22:13), siempre emparejada con Omega para formar un merismo que abarca toda la realidad, desde el principio hasta el fin. Todas las traducciones principales simplemente transliteran el término: Alfa en español, Alpha en inglés, francés y alemán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0002', 'spa', 'Aarón; hermano de Moisés, primer sumo sacerdote de Israel, referido en el NT como arquetipo sacerdotal.', 'Forma griega indeclinable del hebreo אַהֲרוֹן, que designa al hermano de Moisés y primer sumo sacerdote de Israel. En el Nuevo Testamento, Aarón aparece en contextos que fundamentan la legitimidad y tipología sacerdotal. Lucas traza el linaje de Elisabet hasta las hijas de Aarón (Lucas 1:5), Esteban relata el episodio del becerro de oro (Hechos 7:40), y Hebreos invoca a Aarón repetidamente como el referente frente al cual se mide el sacerdocio superior de Cristo (Heb 5:4; 7:11; 9:4). El nombre se transliterado de manera idéntica en todos los idiomas, reflejando su reconocimiento universal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0005', 'spa', 'Abbá (vocativo arameo ''padre''); forma transliterada de dirigirse a Dios que expresa cercanía filial íntima', 'Palabra aramea transliterada directamente al griego, conservando el lenguaje de oración de Jesús y los primeros cristianos. Aparece en Marcos 14:36 (Jesús en Getsemaní), Romanos 8:15 y Gálatas 4:6 (creyentes adoptados como hijos). Siempre acompañada del griego πατήρ (''Padre''), señala tanto la continuidad con las propias oraciones de Jesús como la intimidad que el Espíritu concede a los hijos adoptivos. El término transmite calidez familiar — no un formal ''señor'' sino ''papá'', aunque sin ser meramente casual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0006', 'spa', 'Abel; segundo hijo de Adán, cuya ofrenda justa y sangre inocente se convirtieron en tipo del martirio fiel', 'Abel, del hebreo hevel, designa al segundo hijo de Adán, cuyo sacrificio fue aceptado por Dios y cuyo asesinato a manos de Caín constituye el primer derramamiento de sangre inocente en la Biblia. En el Nuevo Testamento, Jesús invoca «la sangre de Abel» (Mat 23:35; Luc 11:51) como punto de partida de una larga historia de sufrimiento justo. Hebreos 11:4 presenta a Abel como primer ejemplo de fe, y 12:24 contrasta su sangre —que clama justicia— con la sangre de Cristo, que pronuncia una palabra superior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0007', 'spa', 'Abías; nombre de una división sacerdotal y de un rey de Judá', 'Nombre hebreo (que significa ''Yahvé es padre'') que aparece en dos linajes distintos del Nuevo Testamento. Mateo 1:7 menciona a Abías como hijo de Roboam en la genealogía real de Jesús. Lucas 1:5 identifica a Zacarías como perteneciente a ''la clase de Abías'', uno de los veinticuatro turnos sacerdotales establecidos en 1 Crónicas 24. Esto vincula al padre de Juan el Bautista con el servicio sacerdotal organizado del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0010', 'spa', 'Abiud, nombre en la genealogía de Jesús que significa ''mi padre es majestad''', 'Abiud aparece en la genealogía de Jesús según Mateo, mencionado dos veces en el versículo 1:13 como parte del linaje posterior al exilio. Su nombre deriva de raíces hebreas que significan ''mi padre es majestad'' o ''padre de alabanza''. Ocupa un lugar clave en la transición del exilio a la restauración, conectando la línea davídica a través de Zorobabel hasta José. Como muchos nombres en esta sección de la genealogía, Abiud no aparece en los registros del Antiguo Testamento, representando las generaciones anónimas que preservaron la línea mesiánica durante siglos de espera. Su presencia testifica la fidelidad de Dios en guardar la descendencia de David.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0011', 'spa', 'Abraham — el patriarca, padre de Isaac, a quien Dios otorgó el pacto de promesa y la tierra de Canaán.', 'Ἀβραάμ es la transliteración griega indeclinable del hebreo אַבְרָהָם, el gran patriarca de Israel. Cada aparición en el Nuevo Testamento remite al personaje de Génesis 12-25: el hombre llamado desde Ur, receptor del pacto de circuncisión, destinatario de la promesa de una descendencia innumerable y probado con el ofrecimiento de Isaac. En los Evangelios, Jesús invoca a Abraham para redefinir la membresía del pacto: «Dios puede de estas piedras levantar hijos a Abraham» (Mt 3:9). Pablo edifica su teología de la justificación por fe sobre el ejemplo de Abraham (Ro 4; Gá 3:6-9). La expresión «el seno de Abraham» (Lc 16:22) se convirtió en una figura del descanso bienaventurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0012', 'spa', 'El abismo; una profundidad o sima sin fondo, a menudo la prisión subterránea de seres demoníacos o el reino de los muertos.', 'En el griego clásico, ἄβυσσος describía cualquier cosa insondablemente profunda o ilimitada. La Septuaginta lo adoptó para referirse al abismo primordial de Génesis 1:2 y a las grandes profundidades acuáticas. En el Nuevo Testamento adquiere un marcado tono cósmico-escatológico: los demonios en Lucas 8:31 suplican a Jesús que no los envíe al abismo, y en Apocalipsis 9:1-11 es el pozo sellado del que emergen langostas destructoras. Pablo lo emplea en Romanos 10:7 como el reino de los muertos. El español ''abismo'' y el francés ''abîme'' conservan ese mismo sentido de profundidad insondable, mientras que el alemán ''Abgrund'' (literalmente ''sin fondo'') capta vívidamente esa cualidad de ser ilimitado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0013', 'spa', 'Ágabo, profeta cristiano que advirtió sobre una hambruna y el encarcelamiento de Pablo', 'Ágabo fue un profeta de la iglesia primitiva que aparece dos veces en Hechos con advertencias proféticas contundentes. En Hechos 11:28, predijo por el Espíritu una gran hambruna que se extendería por todo el mundo romano, profecía que se cumplió bajo Claudio. En Hechos 21:10, realizó un acto simbólico al estilo de los profetas del Antiguo Testamento: se ató las manos y los pies con el cinturón de Pablo para anunciar vívidamente que este sería atado por los judíos en Jerusalén. Su ministerio ejemplifica la continuidad de los dones proféticos en la iglesia primitiva, proporcionando guía divina para la preparación y las decisiones de la comunidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0014', 'spa', 'Hacer el bien, practicar activamente la beneficencia y las buenas obras', 'Este verbo compuesto enfatiza la acción concreta de hacer el bien, no simplemente ser bueno, sino practicar la beneficencia con energía. En Hechos 14:17, Pablo declara que Dios ''hizo bien'' al dar lluvias y estaciones fructíferas, demostrando su bondad mediante la providencia. En 1 Timoteo 6:18, Pablo ordena a los ricos ''hacer el bien'', ser generosos y estar dispuestos a compartir, transformando la riqueza en benevolencia activa. El verbo capta el bien no como virtud estática sino como acción dinámica: obras buenas que brotan de un carácter bueno. Es la justicia en movimiento, la virtud expresada en beneficio tangible para los demás.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0015', 'spa', 'Hacer el bien, obrar con bondad — realizar acciones moralmente buenas o bondadosas hacia los demás. El verbo ἀγαθοποιέω (agathopoieo) significa ''hacer', 'Hacer el bien, obrar con bondad — realizar acciones moralmente buenas o bondadosas hacia los demás. El verbo ἀγαθοποιέω (agathopoieo) significa ''hacer el bien'' u ''obrar rectamente'', combinando ἀγαθός (bueno) con ποιέω (hacer). Jesús lo emplea de manera incisiva en la controversia del sábado: ''¿Es lícito en sábado hacer el bien o hacer el mal?'' (Marcos 3:4; Lucas 6:9). El Sermón del Llano en Lucas desarrolla aún más esta ética: ''Haced bien a los que os aborrecen'' (6:27, 33, 35). Pedro lo aplica a los creyentes que soportan sufrimiento injusto (1 Pedro 2:15, 20; 3:6, 17). Las traducciones convergen notablemente: español ''hacer bien'', árabe ''صنع خيرًا'', hindi ''भलाई करना'', coreano ''선을 행하다'', suajili ''kufanya mema''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0018', 'spa', 'Bueno; moralmente excelente, virtuoso o beneficioso — de personas, acciones o cosas; también sustantivado como ''bienes'' o ''el bien.''', 'Uno de los adjetivos cardinales del Nuevo Testamento para la excelencia moral, ἀγαθός describe lo que es inherentemente bueno en carácter, calidad o efecto. La provocadora pregunta de Jesús «¿Por qué me llamas bueno?» (Mt 19:17) indaga la naturaleza misma de la bondad divina, mientras que el «buen árbol» que da «buen fruto» (Mt 7:17) hace visible y palpable la calidad moral. Sustantivado, produce «bienes» (Lc 1:53, los hambrientos colmados de bienes) o el principio abstracto del «bien» en sí (Ro 12:9, «aferraos a lo bueno»).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0019', 'spa', 'Bondad, rectitud, excelencia moral; benevolencia activa que va más allá de la simple amabilidad', 'Ἀγαθωσύνη designa una bondad moral robusta: no una inocencia pasiva, sino una rectitud activa y generosa que moldea la manera en que una persona vive y se relaciona con los demás. Pablo la incluye entre el fruto del Espíritu (Gál 5:22) y como componente de la luz del Espíritu (Ef 5:9), emparejándola con la justicia y la verdad. En Romanos 15:14 afirma que los creyentes de Roma están «llenos de bondad», y en 2 Tesalonicenses 1:11 ora para que Dios cumpla todo deseo de bondad. Es virtud con capacidad de acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0020', 'spa', 'Exultación, gozo extremo; alegría intensa, frecuentemente suscitada por el Espíritu, ligada a los actos salvíficos de Dios.', 'Designa un gozo intenso y desbordante que va más allá de la felicidad ordinaria: una exultación profunda vinculada con frecuencia a la acción redentora de Dios. La palabra aparece en momentos decisivos: el ángel anuncia que el nacimiento de Juan traerá «gozo y alegría» (Lucas 1:14), el niño Juan salta de regocijo en el vientre de Elisabet (Lucas 1:44) y la iglesia primitiva parte el pan con este espíritu jubiloso (Hechos 2:46). Hebreos 1:9 cita el Salmo 45, ungiendo al Hijo con «óleo de alegría». Todas estas referencias apuntan a un gozo celebrativo y exultante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0021', 'spa', 'Regocijarse grandemente, exultar — saltar o estremecerse de gozo desbordante, especialmente ante los actos salvíficos de Dios. El verbo ἀγαλλιάω (agal', 'Regocijarse grandemente, exultar — saltar o estremecerse de gozo desbordante, especialmente ante los actos salvíficos de Dios. El verbo ἀγαλλιάω (agalliaō) expresa un gozo tan intenso que roza lo físico: una exultación que difícilmente puede contenerse. El alma de María ''se regocija grandemente'' en Dios su Salvador (Lucas 1:47), Jesús mismo ''se estremeció de gozo en el Espíritu Santo'' (Lucas 10:21), y Abraham ''se regocijó'' al ver el día de Cristo (Juan 8:56). Las Bienaventuranzas prometen esta exultación como recompensa por soportar la persecución (Mateo 5:12). Pedro la aplica a los creyentes que, sin haber visto aún a Cristo, ''se regocijan con gozo inefable'' (1 Pedro 1:8). El español ''regocijarse'' y el francés ''tressaillir de joie'' alcanzan este registro de deleite desbordante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0022', 'spa', 'Soltero/a, no casado/a; persona sin cónyuge, ya sea por no haberse casado nunca o por matrimonio previo disuelto', 'Usado exclusivamente por Pablo en 1 Corintios 7, este adjetivo designa a alguien que actualmente carece de pareja matrimonial. En el griego clásico se aplicaba principalmente a varones (con ἄνανδρος para mujeres), pero Pablo amplía su alcance para incluir ambos sexos, dirigiéndose a viudos en 7:8 y a una esposa separada en 7:11. Las traducciones al español («soltero/soltera») confirman el sentido inclusivo en el NT. Pablo emplea el término pastoralmente, no como estigma social, sino para reflexionar sobre las ventajas espirituales de una devoción indivisa al Señor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0023', 'spa', 'Indignarse, sentir fuerte disgusto o enojo ante algo percibido como injusto o inapropiado.', 'Describe una reaccion emocional intensa de disgusto o indignacion moral, generalmente provocada al presenciar algo percibido como incorrecto o inapropiado. En los Evangelios aparece cuando los discipulos se enojan por lo que consideran una presuncion (Mt 20:24; Mr 10:41) o cuando los lideres religiosos protestan por las alabanzas de la multitud a Jesus (Mt 21:15). La palabra tiene un matiz visceral: sus raices en el griego clasico apuntan a una especie de ebullicion o fermentacion interior del sentimiento. Todas las tradiciones de traduccion convergen en un unico sentido: ''indignarse'' en espanol, ''s''indigner'' en frances, ''unwillig sein'' en aleman, captando un disgusto ya sea justo o interesado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0025', 'spa', 'Amar con voluntad deliberada y devoción; como participio pasivo: amado; en voz pasiva: ser amado.', 'El verbo que soporta el peso de la teología neotestamentaria del amor, ἀγαπάω abarca el amor divino por el mundo (Jn 3:16), el amor del creyente hacia Dios y el prójimo (Mt 22:37-39), y el amor mutuo que define la comunidad cristiana (Jn 13:34-35). Lo distintivo de ἀγαπάω es su capacidad para ser mandado: «amad a vuestros enemigos» (Mt 5:44; Lc 6:27, 35) presupone un amor que opera por voluntad y no por mero sentimiento. El participio perfecto pasivo ἠγαπημένοι («amados») se convirtió en fórmula epistolar de identidad (Col 3:12; 1 Ts 1:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0026', 'spa', 'Amor — el amor abnegado de Dios, el amor mutuo entre creyentes y (raramente) la fiesta de amor de la iglesia primitiva.', 'Ἀγάπη es la palabra emblemática del Nuevo Testamento para el amor, portadora de una profundidad y entrega que distinguió el vocabulario cristiano primitivo. Abarca el amor de Dios por la humanidad (Ro 5:8; 1 Jn 4:8-10), el amor responsivo del creyente hacia Dios y el «mandamiento nuevo» de amor mutuo entre discípulos (Jn 13:34-35). El célebre himno de Pablo en 1 Corintios 13 define el carácter de la ἀγάπη. En un único pasaje, Judas 1:12, la palabra aparece como plural concreto — las «fiestas de amor» (ἀγάπαι) de las comidas comunitarias cristianas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0027', 'spa', 'ἀγαπητός — amado, querido; designación divina del Hijo único y tratamiento afectuoso entre creyentes.', 'El adjetivo ἀγαπητός («amado») deriva del verbo ἀγαπάω y expresa un amor profundo y entrañable. Sus 61 apariciones neotestamentarias se reparten en dos contextos principales. Primero, es la designación divina de Jesús en su bautismo y transfiguración: «Este es mi Hijo amado, en quien tengo complacencia» (Mt 3:17; 17:5; Mr 1:11; 9:7). En la parábola de los labradores malvados, el dueño envía a «su hijo amado» como emisario final (Mr 12:6; Lc 20:13). Segundo, Pablo y los demás autores epistolares lo emplean como tratamiento afectuoso para los creyentes: «amados hermanos» (1 Co 15:58; Fil 4:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0028', 'spa', 'Agar, sierva egipcia de Sara y madre de Ismael', 'Agar fue la esclava egipcia de Sara que se convirtió en concubina de Abraham y dio a luz a Ismael. En Gálatas 4, Pablo emplea su historia de forma alegórica: Agar representa el monte Sinaí y el pacto de esclavitud bajo la ley, correspondiente a la Jerusalén terrenal en servidumbre. Su nombre aparece dos veces en este pasaje (4:24-25) mientras Pablo contrasta dos pactos: uno nacido de la esclavitud (Agar/Sinaí/Jerusalén presente) y otro nacido de la promesa (Sara/Jerusalén celestial). La tipología es compleja y debatida, pero Pablo utiliza a Agar para representar el principio de buscar la justicia mediante la ley en vez de la promesa: esclavitud en lugar de libertad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0029', 'spa', 'Obligar al servicio forzado, requisar mano de obra o recursos por autoridad; compeler a servir como correo', 'Verbo derivado de la práctica imperial persa — el sistema de ἄγγαρος que requisaba suministros y trabajo forzado para los mensajeros reales. Jesús lo emplea en el Sermón del Monte: si alguien te obliga a caminar una milla, ve dos (Mt 5:41). Simón de Cirene fue ''obligado'' a cargar la cruz de Jesús (Mt 27:32, Mc 15:21). El término refleja la práctica romana de reclutar civiles para servicio militar u oficial, vivida como opresiva por los pueblos ocupados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0030', 'spa', 'Vasija, recipiente para contener líquidos o productos secos', 'Este sustantivo designa recipientes o vasijas empleados para contener y almacenar diversos materiales: líquidos, granos, dinero u otros bienes. En Mateo 13:48, se refiere a los recipientes en los que los pescadores recogen los peces buenos al clasificar la pesca. En Mateo 25:4, las vírgenes prudentes llevan aceite en sus vasijas junto con sus lámparas, preparadas para la tardanza del esposo. La palabra enfatiza la función: son receptáculos diseñados para contener y preservar su contenido. Ya sean cestas de pesca, frascos de aceite o tinajas de almacenamiento, el hilo común es la contención y la utilidad práctica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0031', 'spa', 'mensaje, anuncio, proclamación de noticias o enseñanza transmitida con autoridad', 'Este sustantivo designa un mensaje o anuncio: una noticia transmitida desde su origen hasta quien la recibe. En 1 Juan aparece dos veces para introducir proclamaciones fundamentales: «Este es el mensaje que hemos oído de él y os anunciamos» (1:5, sobre Dios como luz) y «Este es el mensaje que habéis oído desde el principio» (3:11, sobre el amor mutuo). La palabra subraya el contenido transmitido —enseñanza o noticia comunicada de Cristo a través de los apóstoles a la iglesia. No es simple información, sino proclamación autorizada, contenido del evangelio que debe ser anunciado y recibido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0032', 'spa', 'Ángel, mensajero — un ser celestial sobrenatural al servicio de Dios, o un enviado humano portador de un mensaje.', 'Ἄγγελος tiende un puente entre el cielo y la tierra en el Nuevo Testamento. En la inmensa mayoría de sus usos designa a los seres celestiales que pueblan la sala del trono de Dios, transmiten anuncios divinos y ejecutan juicios celestiales — desde la anunciación de Gabriel a María (Lc 1:26) hasta los ángeles ante la tumba vacía (Mt 28:2). Sin embargo, el vocablo nunca perdió del todo su significado griego original de «mensajero», y seis veces se refiere a enviados humanos: Juan el Bautista como precursor prometido (Mt 11:10; Mc 1:2), mensajeros enviados por Jesús (Lc 9:52) y los discípulos de Juan que visitan a Jesús (Lc 7:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0033', 'spa', '¡Vamos!, ¡ea!; imperativo fosilizado como interjección que insta a la acción o llama la atención', 'Forma imperativa del verbo ἄγω (''conducir'') que se cristalizó como interjección exhortativa en griego clásico desde Homero. Funciona como partícula discursiva que impulsa mandatos o propuestas: ''¡vamos!'', ''¡ea!'', ''¡anda!''. Se combinaba frecuentemente con νύν (''ahora'') o δή (''pues'') para reforzar la urgencia, y podía preceder verbos en primera persona (''hagamos...''), tercera persona (''que ellos...'') o construcciones con ὅπως y futuro. Su forma plural ἄγετε cumplía la misma función. Aunque sin ocurrencias registradas en este corpus, su presencia como partícula energizante está confirmada en el griego bíblico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0034', 'spa', 'Manada de animales, especialmente cerdos; grupo de ganado que pasta o se desplaza junto.', 'Se refiere a una manada o piara de animales, derivado del verbo ''conducir'' o ''llevar''. En el griego clasico podia designar manadas de caballos, ganado vacuno o incluso bancos de peces, pero todas las apariciones en el Nuevo Testamento se refieren a la celebre piara de cerdos del episodio del endemoniado gadareno (Mt 8:30-32; Mr 5:11-13; Lc 8:32-33). La convergencia entre idiomas es total: espanol ''manada'', frances ''troupeau'', aleman ''Herde'', todos significando simplemente ''manada''. La palabra no aparece en ningun otro lugar del NT, lo que la convierte practicamente en un termino tecnico de la narrativa gadarena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0037', 'spa', 'Santificar, hacer santo, consagrar; apartar para los propósitos de Dios o reverenciar el nombre de Dios como santo', 'Santificar, hacer santo, consagrar; apartar para los propósitos de Dios o reverenciar el nombre de Dios como santo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0038', 'spa', 'Santificación, santidad — el proceso y el estado de ser apartado para Dios, consagración moral. El sustantivo ἁγιασμός (hagiasmos) denota tanto el pro', 'Santificación, santidad — el proceso y el estado de ser apartado para Dios, consagración moral. El sustantivo ἁγιασμός (hagiasmos) denota tanto el proceso de santificación como el estado resultante de santidad. Pablo lo presenta como la meta de la vida cristiana: los creyentes son llamados ''a santificación'' (1 Tesalonicenses 4:3, 7), y Cristo mismo se ha hecho nuestra santificación (1 Corintios 1:30). Romanos 6:19, 22 contrasta el fruto de la santificación con la antigua esclavitud a la impureza. El autor de Hebreos declara que sin santidad nadie verá al Señor (Hebreos 12:14). El término posee tanto una dimensión posicional como progresiva: el creyente ha sido apartado y está siendo apartado. Español ''santificación'', árabe ''تَقْدِيس/قَدَاسَة'', hindi ''पवित्रता'', coreano ''거룩함''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0039', 'spa', 'Santo, sagrado, consagrado a Dios; puro, apartado para el servicio divino', 'Término fundamental para expresar consagración y pureza moral, cuyo sentido original en griego clásico era ''dedicado a los dioses''. En el uso bíblico predomina la connotación positiva: templos y espacios sagrados son ἅγιος; las personas santas o puras ante Dios reciben esta designación; ''los santos'' (οἱ ἅγιοι) se refiere al pueblo de Dios; y el Espíritu Santo es πνεῦμα ἅγιον. La Septuaginta adoptó este término para traducir el hebreo קָדוֹשׁ, consolidando el concepto de separación para Dios. El griego clásico lo usó ocasionalmente con sentido negativo (''maldito''), pero este matiz es raro y está ausente de los textos bíblicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0040', 'spa', 'Santo, sagrado, consagrado; de personas (santos, el Santo), lugares (santuario, lugar santísimo) y cosas dedicadas a Dios.', 'Ἅγιος es uno de los adjetivos teológicos más omnipresentes del Nuevo Testamento, con 235 apariciones en casi todos los libros. En su núcleo reside la idea de estar apartado — separado de lo ordinario y consagrado a Dios. Su versatilidad es notable: describe al Espíritu de Dios mismo (τὸ πνεῦμα τὸ ἅγιον), a la comunidad de creyentes (οἱ ἅγιοι, «los santos»), los recintos del templo (τὰ ἅγια) y objetos o lugares particulares consagrados para uso divino. El arco de la santidad bíblica se traza en este vocablo: Dios es santo, santifica lugares y santifica personas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0042', 'spa', 'Santidad, santificación; pureza moral y consagración a Dios', 'Sustantivo abstracto que expresa la cualidad de estar apartado para Dios en pureza moral. Romanos 1:4 describe al Espíritu como el ''Espíritu de santidad'' que declaró a Jesús Hijo de Dios por el poder de la resurrección. Pablo exhorta a completar la santificación ''en santidad'' (2 Co 7:1) y ora para que los corazones de los creyentes sean establecidos irreprensibles ''en santidad'' ante Dios (1 Ts 3:13). El término enfatiza la consagración ética y espiritual más que la mera pureza ritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0045', 'spa', 'Ancla; instrumento pesado lanzado desde un barco para fijarlo, usado figuradamente para la esperanza firme', 'El ancla era indispensable en la navegación del Mediterráneo antiguo, y las cuatro apariciones neotestamentarias reflejan ese mundo. En Hechos 27, Lucas narra las dramáticas maniobras de anclaje durante la tormenta frente a Malta: los marineros echan cuatro anclas por la popa (27:29), fingen echar anclas por la proa (27:30) y finalmente las cortan (27:40). Hebreos 6:19 transforma la imagen en una poderosa metáfora: la esperanza cristiana es «ancla del alma, segura y firme», que penetra hasta el interior del santuario, detrás del velo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0046', 'spa', 'sin encoger, no tratado ni procesado (referido a tela nueva y cruda)', 'Este adjetivo describe una tela que no ha sido tratada ni encogida: tejido nuevo y crudo, aún sin procesar para su uso. Aparece en la parábola de Jesús sobre el remiendo de vestidos viejos: coser tela sin encoger sobre un vestido viejo provoca un daño peor cuando el parche nuevo se encoge y se desgarra (Mateo 9:16; Marcos 2:21). La palabra capta la incompatibilidad entre lo nuevo y lo viejo, ilustrando por qué el vino nuevo del reino no puede contenerse en los odres viejos de las estructuras religiosas existentes. El remiendo sin encoger representa una novedad cruda que inevitablemente genera tensión con el tejido envejecido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0047', 'spa', 'pureza, castidad, santidad moral y sexual', 'Este sustantivo denota pureza, particularmente en la conducta moral y sexual: santidad que se manifiesta en castidad y vida limpia. En las cartas pastorales de Pablo a Timoteo aparece dos veces: entre las cualidades que Timoteo debe modelar (1 Timoteo 4:12) y como la actitud con la que debe tratar a las mujeres jóvenes, como hermanas «en toda pureza» (5:2). La palabra enfatiza no meramente una limpieza ritual, sino integridad moral, especialmente dominio propio sexual y límites apropiados. Es la cualidad de quien tiene una conducta sin mancha, cuyas relaciones respetan los límites debidos y cuyo carácter refleja santidad en la vida práctica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0048', 'spa', 'Purificar, hacer ceremonial o moralmente limpio; en voz media/pasiva: purificarse o ser purificado.', 'Derivado de hagnos (''puro, santo''), este verbo abarca tanto la purificacion ritual como la moral en el Nuevo Testamento. En Hechos aparece en formas media y pasiva para la purificacion ceremonial judia: Pablo purificandose antes de entrar al templo (Hch 21:24, 26; 24:18) y los peregrinos judios purificandose antes de la Pascua (Jn 11:55). Santiago 4:8 tiende un puente entre lo ceremonial y lo moral: ''purificad vuestros corazones, hombres de doble animo''. En su uso activo transitivo, describe a los creyentes purificando sus almas mediante la obediencia a la verdad (1 P 1:22) y la esperanza del retorno de Cristo purificando a quien la sostiene (1 Jn 3:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0050', 'spa', 'Ignorar, desconocer; ser desconocido o no reconocido; ser deliberadamente desatendido', 'Ignorar, desconocer; ser desconocido o no reconocido; ser deliberadamente desatendido');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0052', 'spa', 'ignorancia; falta de conocimiento o conciencia, especialmente respecto a los propósitos de Dios o las normas morales', 'En el griego clásico, ἄγνοια designa una falta de percepción o entendimiento, opuesta a ἐπιστήμη (conocimiento). Los autores del NT le confieren un peso teológico profundo: Pedro atribuye la crucifixión a la ignorancia del pueblo (Acts 3:17), Pablo declara que Dios pasó por alto los tiempos de ignorancia (Acts 17:30), y tanto Pablo como Pedro vinculan la ignorancia con la oscuridad moral de la vida pagana (Eph 4:18; 1 Pet 1:14). El término español ''ignorancia'' refleja con precisión este campo semántico, abarcando tanto el desconocimiento intelectual como la ceguera espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0053', 'spa', 'Puro, casto, inocente; moralmente intachable y libre de contaminación o de motivos mezclados.', 'Adjetivo que describe lo moralmente inmaculado: limpio en motivos, conducta y carácter. Pablo lo usa para elogiar el arrepentimiento ferviente de los corintios, declarándolos ''puros en este asunto'' (2 Co 7:11), y desea presentar a la iglesia como una ''virgen pura'' ante Cristo (2 Co 11:2). En Filipenses 4:8 aparece entre las virtudes dignas de reflexión constante. Las Epístolas Pastorales lo aplican a la conducta personal: conservarse puro (1 Ti 5:22) y el llamado a que las mujeres jóvenes sean castas (Tit 2:5). El español ''puro/casto'' y el alemán ''rein'' captan esa doble dimensión de pureza moral y ritual que está en el corazón de esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0054', 'spa', 'pureza, sinceridad, integridad moral y devoción sin mezcla', 'Este sustantivo enfatiza pureza, integridad y sinceridad: limpieza moral que brota de una devoción indivisa. En 2 Corintios 6:6, Pablo lo incluye entre las credenciales de su ministerio junto al conocimiento, la paciencia y la bondad, como cualidades que autentican el servicio apostólico. En 2 Corintios 11:3, Pablo teme que los corintios pierdan «la pureza y sinceridad hacia Cristo» por la seducción de falsas enseñanzas, así como Eva fue engañada. La palabra denota no una mera corrección moral externa, sino integridad interior, sencillez de corazón, devoción sin mezcla. Es la cualidad de quien tiene motivos puros y una lealtad indivisa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0056', 'spa', 'ignorancia, falta de conocimiento, especialmente de Dios y de la verdad', 'Este sustantivo denota ignorancia: el estado de no conocer, particularmente respecto a la verdad espiritual y moral. En 1 Corintios 15:34, Pablo ordena con severidad a los corintios que se despierten y dejen de pecar, declarando que «algunos tienen ignorancia de Dios», una acusación devastadora dentro de una iglesia. En 1 Pedro 2:15, los cristianos son llamados a silenciar la ignorancia de los insensatos mediante una buena conducta. La palabra no señala una simple falta inocente de información, sino una ignorancia culpable: el estado de no saber lo que se debería saber. Es especialmente condenatoria cuando se refiere al conocimiento de Dios, una ignorancia con consecuencias morales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0058', 'spa', 'Plaza, mercado público — el espacio cívico abierto destinado al comercio, la vida social, los procedimientos legales y las reuniones cotidianas. La ἀγ', 'Plaza, mercado público — el espacio cívico abierto destinado al comercio, la vida social, los procedimientos legales y las reuniones cotidianas. La ἀγορά (agora) era el corazón comercial y cívico de las ciudades antiguas, funcionando como mercado, lugar de encuentro y tribunal informal a la vez. Jesús compara a su generación con niños sentados en la plaza llamándose unos a otros (Mateo 11:16; Lucas 7:32), y reprende a los escribas y fariseos que aman los saludos en las plazas (Mateo 23:7; Marcos 12:38; Lucas 11:43). En Marcos 6:56, los enfermos son colocados en las plazas con la esperanza de ser sanados. El lavamiento ritual de los fariseos de las cosas procedentes ''del mercado'' (Marcos 7:4) refleja preocupaciones de pureza por el contacto con gentiles y personas impuras en ese espacio público. El español ''plaza'' y el francés ''place du marché'' capturan el doble carácter comercial y cívico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0059', 'spa', 'Comprar, adquirir; se usa tanto para el comercio en el mercado como teológicamente para la compra redentora de los creyentes por parte de Cristo.', 'Comprar, adquirir; se usa tanto para el comercio en el mercado como teológicamente para la compra redentora de los creyentes por parte de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0060', 'spa', 'Relativo al mercado; días de audiencia judicial; gente vulgar o de la calle', 'Este adjetivo se vincula con el ágora o plaza del mercado, abarcando el lugar, sus actividades y quienes lo frecuentan. En Hechos 17:5, describe a los ociosos de la plaza, gente vulgar que los judíos reclutaron para provocar un disturbio en Tesalónica. En Hechos 19:38, el escribano menciona los «días de audiencia», las sesiones regulares en que se celebraban juicios. El término abarca así ubicación física, procedimientos judiciales y clase social, todo conectado con la plaza como centro cívico y comercial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0061', 'spa', 'Pesca, redada de peces; el resultado de pescar o cazar', 'Este sustantivo designa la captura o redada de peces: la presa obtenida en la pesca. En Lucas 5 aparece dos veces durante la pesca milagrosa: Jesús indica a Pedro que eche las redes para una pesca (5:4), y la cantidad atrapada fue tan grande que las redes comenzaban a romperse (5:9). La palabra enfatiza el resultado, no el acto de pescar, sino la captura lograda. En la narración de Lucas, esa pesca desbordante se convierte en señal que mueve a Pedro a seguir a Jesús y hacerse pescador de hombres.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0065', 'spa', 'Olivo silvestre, acebuche; el olivo no cultivado en contraste con el injertado', 'Este término designa el olivo silvestre o acebuche, en contraste con el olivo cultivado de huerto. En Romanos 11, Pablo desarrolla una metáfora extensa: los creyentes gentiles son como ramas de un olivo silvestre injertadas contra natura en el olivo cultivado (los privilegios del pacto de Israel). La palabra aparece dos veces (11:17, 24) para subrayar el contraste entre lo silvestre y lo cultivado. El olivo silvestre produce fruto inferior y normalmente se injertaría en tronco cultivado, no al revés. El argumento de Pablo reside precisamente en esa inversión: Dios ha hecho lo inesperado, injertando ramas silvestres (los gentiles) en el árbol cultivado (Israel).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0066', 'spa', 'Salvaje, silvestre, indómito; que vive en estado natural, opuesto a lo doméstico o cultivado', 'Adjetivo que distingue lo salvaje de lo domesticado — animales no domados por el ser humano, plantas que crecen de forma natural frente a las cultivadas. Juan el Bautista comía ''miel silvestre'' en el desierto (Mt 3:4, Mc 1:6). Judas 13 emplea ''fieras olas del mar'' como metáfora del comportamiento desvergonzado de los falsos maestros. El uso clásico contrasta bestias salvajes con mansas, árboles silvestres con cultivados — el ámbito de la naturaleza frente al orden humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0067', 'spa', 'Agripa — Herodes Agripa II, el último rey herodiano, ante quien Pablo presentó su defensa en Cesarea. Ἀγρίππας (Agrippas) en el Nuevo Testamento se re', 'Agripa — Herodes Agripa II, el último rey herodiano, ante quien Pablo presentó su defensa en Cesarea. Ἀγρίππας (Agrippas) en el Nuevo Testamento se refiere exclusivamente a Herodes Agripa II, bisnieto de Herodes el Grande y último gobernante de la dinastía herodiana. Aparece en Hechos 25–26, llegando a Cesarea con su hermana Berenice para rendir homenaje al nuevo gobernador Festo. Pablo aprovecha la audiencia como oportunidad para una defensa completa de su conversión y misión apostólica (Hechos 26:1-29). La famosa respuesta de Agripa — ''Por poco me persuades a hacerme cristiano'' (Hechos 26:28) — ha resonado a lo largo de siglos de predicación. El español ''Agripa'' y el francés ''Agrippa'' transliteran directamente de la forma latino-griega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0068', 'spa', 'Un campo o terreno cultivado; en plural, el campo abierto o zona rural que rodea una población.', 'Un campo o terreno cultivado; en plural, el campo abierto o zona rural que rodea una población.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0069', 'spa', 'velar, estar alerta; mantenerse despierto con vigilancia espiritual y disposición constante a la oración', 'Originalmente con el sentido de pasar la noche en vela o sufrir insomnio, ἀγρυπνέω adquiere en el NT un profundo sentido metafórico de vigilancia espiritual. Jesús lo ordena en el discurso escatológico (Mark 13:33), Lucas lo empareja con la oración (Luke 21:36), Pablo lo vincula con la intercesión perseverante (Eph 6:18), y Hebreos lo aplica a la supervisión pastoral: líderes que ''velan'' por las almas (Heb 13:17). La imagen del centinela que permanece despierto captura fielmente la esencia de este término en todas sus apariciones neotestamentarias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0070', 'spa', 'Desvelo, insomnio; vigilia nocturna con atención vigilante', 'Este sustantivo denota desvelo o vigilia: noches pasadas en estado de alerta en lugar de dormir. En 2 Corintios, Pablo lo menciona dos veces entre sus penalidades apostólicas: noches en vela soportadas al servicio del ministerio (6:5; 11:27). No se trata de simple insomnio, sino de vigilancia con propósito: noches dedicadas a la oración, al cuidado de las iglesias o a circunstancias que impedían el descanso. La palabra capta tanto la privación física como la entrega vigilante que caracterizó el ministerio de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0071', 'spa', 'Llevar, traer, conducir; intransitivamente: ir; en sentido figurado: guiar o dirigir.', 'ἄγω es uno de los verbos de movimiento más fundamentales del griego, abarcando toda la gama de desplazamiento dirigido con personas. En su sentido básico significa llevar o traer a alguien de un lugar a otro: soldados que escoltan a Jesús ante Pilato, el Espíritu que conduce a Cristo al desierto, discípulos que traen un pollino. Pero también funciona intransitivamente en la exhortación urgente ἄγωμεν («¡vamos!») en momentos de crisis (Mt 26:46; Jn 11:7). La extensión figurada donde el Espíritu «guía» a los creyentes (Ro 8:14; Gá 5:18) muestra el mismo verbo operando en los dominios físico y espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0073', 'spa', 'Contienda, lucha o carrera; el ambito del esfuerzo, ya sea combate espiritual o competicion atletica (ἀγών).', 'Enraizado en el mundo del atletismo griego, este sustantivo traslada la energia de un esfuerzo intenso al ambito espiritual. Pablo lo utiliza para describir la lucha continua del creyente por la fe: la ''buena batalla'' de 1 Timoteo 6:12 y 2 Timoteo 4:7, el conflicto soportado en Filipos (Fil 1:30) y la batalla invisible librada por los colosenses (Col 2:1). En Hebreos 12:1 la metafora se transforma en una carrera a pie, con la ''nube de testigos'' como espectadores. El espanol distingue lucha/pelea (''fight/struggle'') de carrera (''race''), revelando las dos imagenes distintas en juego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0075', 'spa', 'Contender, esforzarse, luchar — desde la competencia atlética hasta la guerra espiritual y el combate literal.', 'Tomado del mundo de los juegos atléticos griegos, este verbo traslada la intensidad de un competidor que se esfuerza por el premio al corazón de la espiritualidad neotestamentaria. La declaración de despedida de Pablo, ''he peleado la buena batalla'' (2 Ti 4:7), y su mandato de ''pelear la buena batalla de la fe'' (1 Ti 6:12), emplean la misma palabra que describía a luchadores y corredores en la arena. Jesús ordena a sus oyentes ''esforzarse por entrar por la puerta estrecha'' (Lc 13:24), mientras que Epafras ''lucha constantemente'' en oración por los colosenses (Col 4:12). Solo en Juan 18:36 aflora el sentido militar literal, donde Jesús dice que sus servidores ''pelearían'' si su reino fuera de este mundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0076', 'spa', 'Adán; el primer hombre creado por Dios, usado como ancestro genealógico y figura tipológica contrastada con Cristo.', 'Adán es el nombre hebreo que significa ''hombre'' o ''humanidad'', incorporado al griego como sustantivo propio indeclinable. Lucas remonta la genealogía de Jesús hasta Adán, hijo de Dios (Lc 3:38), anclando así la plena humanidad del Salvador. Pablo desarrolla a Adán como la gran contraparte tipológica de Cristo: por un solo hombre entró el pecado (Ro 5:14), en Adán todos mueren pero en Cristo todos serán vivificados (1 Co 15:22), y el ''postrer Adán'' fue hecho espíritu vivificante (1 Co 15:45). Las formas en español ''Adán'' y en francés ''Adam'' muestran cuán universalmente este nombre pasa inalterado entre lenguas, subrayando su papel fundacional en la teología bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0079', 'spa', 'Hermana: una hermana de sangre o una creyente en la comunidad cristiana', 'Hermana: una hermana de sangre o una creyente en la comunidad cristiana');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0080', 'spa', 'Hermano; correligionario; pariente — el término principal del NT para el hermano biológico o el miembro de la familia espiritual.', 'Del griego ἀδελφός, literalmente «del mismo vientre», esta palabra opera en un doble registro en el Nuevo Testamento. En un puñado de pasajes designa al hermano de sangre — Santiago y Juan, o los propios hermanos de Jesús. Pero en la inmensa mayoría de sus 343 apariciones se dirige a los creyentes como familia, haciendo vividamente relacional la autocomprensión de la iglesia primitiva. El español «hermanos», el francés «frère» y el alemán «Bruder» conservan esta misma amplitud, y el predominio del plural en todas las lenguas subraya el dominio del sentido comunitario en el uso apostólico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0081', 'spa', 'Hermandad; la comunidad de creyentes como hermanos espirituales en Cristo', 'Este sustantivo designa la hermandad: la comunidad de creyentes unidos como hermanos espirituales en Cristo. En 1 Pedro aparece dos veces con implicaciones éticas: «amad a la hermandad» (2:17) como mandato específico junto a temer a Dios y honrar al emperador, y «vuestra hermandad en todo el mundo» padece los mismos sufrimientos (5:9). El término subraya vínculos familiares entre cristianos, no mera asociación sino parentesco: hermanos que comparten una paternidad común en Dios. Es la iglesia concebida como familia, una red de hermanos y hermanas unidos por nacimiento espiritual más que por sangre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0082', 'spa', 'Poco claro, invisible, oculto a la vista o incierto en su resultado', 'Este adjetivo describe lo que es poco claro, oculto o incierto: lo que no resulta evidente a la vista ni al entendimiento. En Lucas 11:44, Jesús condena a los fariseos comparándolos con sepulcros sin señalizar, sobre los que la gente camina sin darse cuenta de la contaminación que encierran. En 1 Corintios 14:8, Pablo argumenta que si la trompeta emite un sonido confuso, ¿quién se preparará para la batalla? La palabra subraya la falta de claridad: lo que permanece oculto, oscurecido o ambiguo en su señal. Es lo opuesto a lo manifiesto, aquello que no logra comunicarse con nitidez o que permanece escondido de la observación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0085', 'spa', 'Estar profundamente angustiado, turbado en el espíritu; experimentar aflicción o consternación interior', 'Verbo que expresa una intensa turbación interior y ansiedad del alma. Jesús estuvo «profundamente angustiado» en Getsemaní (Mt 26:37, Mr 14:33), y Epafrodito se «afligió» al saber que los filipenses habían oído de su enfermedad (Fil 2:26). En el griego clásico incluye la idea de desconcierto o consternación. El término sugiere algo más que simple tristeza: una profunda desorientación o agitación turbulenta del espíritu, un malestar que sacude al ser entero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0086', 'spa', 'Hades — el reino invisible de los muertos, la morada subterránea de los espíritus de los difuntos en la cosmología del Nuevo Testamento. El sustantivo', 'Hades — el reino invisible de los muertos, la morada subterránea de los espíritus de los difuntos en la cosmología del Nuevo Testamento. El sustantivo ᾅδης (Hades) designa el reino de los muertos, el destino subterráneo de las almas que han partido. En la Septuaginta traduce el hebreo שְׁאוֹל (Seol), y en el Nuevo Testamento conserva ese sentido cosmológico. Jesús advierte que Capernaúm será derribada hasta el Hades (Mt 11:23; Lc 10:15) y declara que las puertas del Hades no prevalecerán contra su iglesia (Mt 16:18). La parábola del rico y Lázaro sitúa el tormento consciente ''en el Hades'' (Lc 16:23). Pedro cita el Salmo 16 para afirmar que Dios no abandonó el alma de Cristo en el Hades (Hch 2:27, 31).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0088', 'spa', 'Incesante, continuo sin interrupción ni pausa', 'Este adjetivo describe lo que es incesante o continuo, sin interrupción ni pausa. En Romanos 9:2, Pablo habla de su ‘dolor incesante’ por el rechazo de Israel al Mesías: una angustia que no cesa, un pesar constante. En 2 Timoteo 1:3, menciona su ‘recuerdo incesante’ de Timoteo en sus oraciones: mención constante, oración sin interrupción. La palabra enfatiza continuidad y persistencia, un estado o actividad que no se detiene ni se debilita. Es la cualidad de lo que permanece constante e ininterrumpido en su ocurrencia o intensidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0089', 'spa', 'incesantemente, sin interrupción; de manera constante y persistente, especialmente referido a la oración y la acción de gracias', 'Este adverbio, derivado de ἀδιάλειπτος (''ininterrumpido''), aparece cuatro veces en las cartas de Pablo, siempre en relación con la oración o la devoción espiritual. Pablo asegura a los romanos que los menciona ''sin cesar'' en sus oraciones (Rom 1:9), da gracias a Dios ''incesantemente'' por la obra de fe y el trabajo de amor de los tesalonicenses (1 Thess 1:3), reconoce su recepción de la palabra ''sin cesar'' (1 Thess 2:13) y da el célebre imperativo de ''orar sin cesar'' (1 Thess 5:17). No exige actividad literal ininterrumpida, sino un patrón de vida marcado por la constancia devocional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0090', 'spa', 'Incorruptible, imperecedero; no sujeto a deterioro ni corrupción; moralmente íntegro e incorruptible', 'Este término describe aquello que no puede ser corrompido ni destruido. En contextos morales denota una integridad que no admite compromiso: jueces que no se dejan sobornar, testigos que no se pueden comprar, magistrados que permanecen honestos. También posee un sentido físico de imperecibilidad, describiendo lo que perdura sin deterioro. La literatura griega antigua lo aplicó tanto al carácter (íntegro, casto) como a la sustancia (inalterable, no afectado por la descomposición). Este doble significado —incorruptibilidad moral e imperecibilidad física— se superpone con frecuencia en el uso bíblico, donde las realidades eternas son a la vez moralmente puras y físicamente indestructibles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0091', 'spa', 'Hacer mal, dañar o perjudicar; actuar injustamente o sufrir agravio', 'Hacer mal, dañar o perjudicar; actuar injustamente o sufrir agravio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0092', 'spa', 'Delito, fechoría, crimen; acto concreto de injusticia o transgresión de la ley', 'Sustantivo que designa actos ilícitos concretos, no la injusticia en abstracto sino fechorías específicas. Galión indica a los judíos que presenten denuncias legítimas sobre verdaderos «delitos» (Hch 18:14). Tértulo desafía a los acusadores de Pablo a declarar qué «fechoría» hallaron en él (Hch 24:20). Apocalipsis 18:5 describe los pecados de Babilonia acumulándose: sus «crímenes» recordados por Dios. El griego clásico distingue este término del error accidental como un mal intencional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0093', 'spa', 'Injusticia, iniquidad, maldad: desviación moral del estándar divino de rectitud, tanto en acto como en condición', 'Injusticia, iniquidad, maldad: desviación moral del estándar divino de rectitud, tanto en acto como en condición');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0094', 'spa', 'Injusto, inicuo; describe a personas que actuan con maldad o a cosas que carecen de rectitud moral, opuesto a δίκαιος. La negacion directa de δίκαιος ', 'Injusto, inicuo; describe a personas que actuan con maldad o a cosas que carecen de rectitud moral, opuesto a δίκαιος. La negacion directa de δίκαιος (''justo''), este adjetivo senala a una persona o cosa como moralmente torcida, injusta o carente de integridad ante Dios. Pablo advierte que los injustos no heredaran el reino de Dios (1 Co 6:1, 9), y Jesus observa que el infiel en lo muy poco tambien es infiel en lo mucho (Lc 16:10-11). Dios hace llover sobre justos e injustos por igual (Mt 5:45), y Pedro declara que el Senor sabe reservar a los injustos para el juicio (2 P 2:9). La autofelicitacion del fariseo — ''no soy como los demas hombres, injustos'' (Lc 18:11) — subraya ironicamente el peso moral de esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0096', 'spa', 'Que no pasa la prueba, descalificado, inútil; rechazado tras ser examinado por no cumplir con el estándar.', 'Tomado del lenguaje del ensayo de metales y la verificación de monedas, este adjetivo describe aquello que no supera el escrutinio y por tanto es rechazado como falso o deficiente. Pablo lo aplica con fuerza al ámbito moral-espiritual: en Romanos 1:28, quienes se negaron a ''aprobar'' (δοκιμάζειν) a Dios fueron entregados a una mente ''reprobada'' (ἀδόκιμος) — un juego de palabras devastador. En 1 Corintios 9:27 teme quedar ''descalificado'' después de haber predicado a otros. El término aparece tres veces en 2 Corintios 13:5-7 cuando Pablo desafía a los corintios a examinarse para ver si son genuinos. El español ''descalificado/reprobado'' conserva tanto la dimensión de prueba como la de rechazo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0101', 'spa', 'Será imposible, forma futura que expresa incapacidad o imposibilidad', 'Este verbo en tiempo futuro declara que algo será imposible, incapaz de ocurrir. Jesús lo emplea en dos contextos similares: en Mateo 17:20, afirma que nada será imposible para quienes tengan fe como un grano de mostaza; en Lucas 1:37, el ángel anuncia a María que nada será imposible para Dios. El verbo enfatiza una imposibilidad categórica que, sin embargo, puede ser revertida: por la fe en Mateo, por el poder de Dios en Lucas. Nombra lo imposible precisamente para declarar que Dios trasciende tales límites.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0102', 'spa', 'Imposible (referido a cosas o situaciones); impotente, débil (referido a personas). El adjetivo ἀδύνατος (del prefijo privativo alfa + δυνατός, ''capaz', 'Imposible (referido a cosas o situaciones); impotente, débil (referido a personas). El adjetivo ἀδύνατος (del prefijo privativo alfa + δυνατός, ''capaz'') posee dos sentidos claramente distintos según se aplique a cosas o a personas. Aplicado a cosas, significa ''imposible'' —lo que no se puede realizar—, sentido cristalizado en la declaración repetida de Jesús de que lo que es imposible para los hombres es posible para Dios (Mt 19:26; Mc 10:27; Lc 18:27). Aplicado a personas, significa ''impotente'' o ''débil'' —alguien que carece de fuerza física o capacidad moral—, como el hombre cojo en Listra (Hch 14:8) y los ''débiles en la fe'' a quienes los fuertes deben sobrellevar (Ro 15:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0103', 'spa', 'Cantar, especialmente himnos o cánticos espirituales en adoración; alabanza vocal dirigida a Dios.', 'Verbo griego estándar para cantar, empleado en el Nuevo Testamento exclusivamente en contextos de adoración: cantar salmos, himnos y cánticos espirituales a Dios. Pablo instruye a los creyentes a cantar y hacer melodía en sus corazones al Señor (Ef 5:19; Col 3:16), mientras las visiones de Apocalipsis presentan a seres celestiales entonando un «cántico nuevo» ante el Cordero (Ap 5:9; 14:3; 15:3). La forma griega clásica ᾄδω (contraída de ἀείδω) tenía asociaciones poéticas más amplias, pero el uso neotestamentario la reserva para la alabanza musical vocal dirigida a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0104', 'spa', 'Siempre, en todo momento; denota recurrencia continua o habitual.', 'Adverbio temporal que significa ''siempre'' o ''en todo momento'', indicando algo que ocurre de manera continua o sin cesacion. En el Nuevo Testamento aparece en contextos que van desde la acusacion de Esteban de que Israel ''siempre'' resiste al Espiritu Santo (Hch 7:51) hasta la paradoja de Pablo de ''morir siempre y sin embargo vivir'' (2 Co 4:11; 6:10). El proverbio cretense citado en Tito 1:12 lo emplea para caracterizar un comportamiento habitual. En todos los idiomas la traduccion es notablemente consistente: espanol ''siempre'', frances ''toujours'', aleman ''immer'', una palabra cuyo significado ha permanecido estable durante milenios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0105', 'spa', 'Águila o buitre; ave rapaz grande usada como símbolo de rapidez, poder y juicio divino.', 'Se refiere al águila (o posiblemente al buitre leonado), un ave rapaz majestuosa que porta un rico simbolismo tanto en la tradición clásica como bíblica. Jesús emplea la imagen de forma proverbial: «donde esté el cadáver, allí se juntarán las águilas» (Mt 24:28; Lc 17:37), evocando probablemente a los buitres que convergen sobre los muertos, una vívida estampa del juicio inevitable. En Apocalipsis, uno de los cuatro seres vivientes tiene rostro de águila (Ap 4:7), un águila clama «¡ay!» en medio del cielo (Ap 8:13), y la mujer perseguida recibe alas de águila para escapar (Ap 12:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0106', 'spa', 'Sin levadura; especialmente como sustantivo: pan sin levadura, la Fiesta de los Panes sin Levadura (τὰ Ἄζυμα).', 'Adjetivo que significa ''sin levadura'', empleado abrumadoramente como sustantivo en el Nuevo Testamento. En los Evangelios Sinópticos aparece en la expresión ''la fiesta de los panes sin levadura'' (τὰ Ἄζυμα), designando la celebración de una semana posterior a la Pascua durante la cual solo se consumía pan elaborado sin fermento (Mt 26:17; Mr 14:1, 12; Lc 22:1, 7). Pablo retoma este trasfondo ritual de manera metafórica en 1 Corintios 5:7-8, exhortando a los creyentes a ser ''sin levadura'' — puros y libres de la vieja levadura de la maldad. Tanto el uso literal como el figurado convergen en la idea central de pureza y ausencia de fermento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0107', 'spa', 'Azor, nombre en la genealogía de Jesús perteneciente al período posterior al exilio', 'Azor aparece en la genealogía de Jesús en Mateo en versículos consecutivos (1:13-14), representando una de las generaciones post-exílicas que conectan la línea de Zorobabel con José. El nombre probablemente significa ‘ayudador’, derivado de raíces hebreas. Como muchos personajes de esta sección genealógica, Azor es desconocido fuera del registro de Mateo: uno de los eslabones oscuros que preservaron el linaje de David a través de los siglos silenciosos. Su doble mención establece su lugar en la cadena de Abiud a Sadoc, portador anónimo pero vital de la promesa mesiánica durante generaciones que esperaron su cumplimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0109', 'spa', 'Aire, atmósfera; la región inferior que rodea la tierra, a veces con connotaciones espirituales.', 'Designa el aire o atmósfera, el medio invisible que envuelve la vida terrenal. En el griego clásico significaba originalmente niebla o bruma (distinto del luminoso αἰθήρ superior), pero en el período neotestamentario se había ampliado para significar simplemente ''aire''. Pablo lo emplea tanto en sentido literal como con peso teológico: en Ef 2:2 Satanás es ''el príncipe de la potestad del aire'', invistiendo la atmósfera de amenaza espiritual, mientras que en 1 Ts 4:17 los creyentes encuentran al Señor ''en el aire''. En 1 Co 9:26 y 14:9 aparece en expresiones idiomáticas — ''golpear el aire'' y ''hablar al aire'' — para acciones inútiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0110', 'spa', 'Inmortalidad, condición de no estar sujeto a la muerte ni a la corrupción', 'Sustantivo que expresa la cualidad de estar más allá de la muerte. Pablo lo emplea escatológicamente: cuando lo mortal se revista de inmortalidad en la resurrección (1 Co 15:53-54), la muerte será absorbida en victoria. Solo Dios posee la inmortalidad de manera intrínseca (1 Ti 6:16), pues «habita en luz inaccesible». Para los creyentes, la inmortalidad es una transformación futura, no una posesión presente. El griego clásico lo usaba para la naturaleza imperecedera de los dioses.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0111', 'spa', 'Ilícito, contrario a la ley divina o moral, prohibido', 'Este adjetivo describe lo que es ilícito o contrario a la ley establecida, particularmente la ley divina o moral. En Hechos 10:28, Pedro explica a Cornelio que es ‘ilícito’ para un judío asociarse con gentiles, aunque Pedro ha aprendido que Dios ha purificado a todos los pueblos. En 1 Pedro 4:3, describe las idolatrías ‘ilícitas’ que los gentiles practicaban en su vida pagana anterior. La palabra enfatiza la transgresión de la ley o la costumbre, una conducta que sobrepasa los límites establecidos. Lleva un peso moral, marcando el comportamiento como indebido, prohibido, fuera de lo lícito y lo justo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0113', 'spa', 'sin ley, sin principios, viviendo sin consideración por la ley divina', 'Este adjetivo describe a aquellos que son sin ley o sin principios—viviendo sin consideración por la ley apropiada o las normas morales. En 2 Pedro, aparece dos veces describiendo a los impíos: Lot fue atormentado por la conducta ''inicua'' de Sodoma (2:7), y los creyentes deben guardarse de ser arrastrados por el error de personas ''sin ley'' (3:17). La palabra enfatiza no simplemente quebrantar leyes específicas, sino una actitud fundamental de anarquía, vivir sin principios o consideración por las normas divinas. Es la cualidad de aquellos que rechazan la ley moral como marco rector.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0114', 'spa', 'Rechazar, desechar o anular; tratar a una persona o un decreto con autoridad como inválido o indigno de aceptación.', 'Rechazar, desechar o anular; tratar a una persona o un decreto con autoridad como inválido o indigno de aceptación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0115', 'spa', 'anulación, dejar a un lado, abolición o cancelación', 'Este sustantivo denota un dejar a un lado, anulación o abolición—la cancelación de lo que fue previamente establecido. En Hebreos 7:18, describe la ''anulación'' del mandamiento anterior (la ley del sacerdocio levítico) debido a su debilidad e inutilidad. En Hebreos 9:26, se refiere a la ''remoción'' del pecado mediante el sacrificio de Cristo. La palabra enfatiza eliminación, abolición, el dejar a un lado lo que anteriormente estaba vigente. Es particularmente significativa en el argumento de Hebreos sobre la superioridad del sacerdocio de Cristo: lo antiguo ha sido anulado, el pecado ha sido removido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0116', 'spa', 'Atenas; la célebre ciudad griega, centro de filosofía y cultura, donde Pablo predicó en el Areópago', 'Atenas (Ἀθῆναι), la célebre ciudad de la antigua Ática, aparece cuatro veces en el NT, todas vinculadas al segundo viaje misionero de Pablo. Lucas registra la llegada de Pablo (Acts 17:15), su indignación ante la idolatría de la ciudad (Acts 17:16) y su partida hacia Corinto (Acts 18:1). Pablo mismo recuerda haber enviado a Timoteo de regreso desde Atenas (1 Thess 3:1). La forma plural (como Θῆβαι) refleja la convención antigua. Todas las traducciones conservan el nombre propio con mínima adaptación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0117', 'spa', 'atenienses, habitantes o ciudadanos de Atenas', 'Este adjetivo-como-sustantivo designa a los atenienses—habitantes y ciudadanos de Atenas, el famoso centro intelectual y cultural del mundo griego antiguo. En Hechos 17, aparece dos veces: los atenienses y residentes extranjeros pasaban su tiempo en nada sino hablar y escuchar nuevas ideas (17:21), y Pablo se dirige al concilio ateniense en el Areópago (17:22). La palabra marca a estas personas por su identidad de ciudad, llevando connotaciones de la reputación de Atenas por filosofía, retórica y amor por la novedad. Representan la sofisticada cultura griega encontrándose con el evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0118', 'spa', 'competir, contender como atleta en juegos o lucha', 'Este verbo denota competir o contender, particularmente como atleta en juegos. En 2 Timoteo 2:5, Pablo usa la metáfora atlética dos veces en un verso: un atleta no recibe la corona a menos que compita según las reglas. El verbo enfatiza el esfuerzo disciplinado de la competencia atlética—no participación casual sino contención seria por la victoria. Pablo aplica esto a la vida y ministerio cristiano: como atletas, los creyentes deben competir según las reglas (las normas de Dios) para recibir el premio. Es esfuerzo disciplinado y regido por normas hacia una meta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0121', 'spa', 'inocente, sin culpa, libre de reproche o sin merecer castigo', 'Este adjetivo describe a uno que es inocente, sin culpa, o libre de merecer castigo. En Mateo 27, aparece dos veces respecto a la crucifixión de Jesús: Judas confiesa que traicionó ''sangre inocente'' (27:4), y Pilato se declara inocente de ''la sangre de este justo'' (27:24). La palabra enfatiza la ausencia de culpa o culpabilidad, uno que no merece el castigo amenazado o impuesto. Es particularmente poderosa en la narrativa de la pasión de Mateo: múltiples testigos reconocen la inocencia de Jesús aun cuando participan en Su ejecución. El inocente sufre por los culpables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0123', 'spa', 'Playa, orilla; franja arenosa o pedregosa de la costa usada como lugar de desembarco o reunión.', 'En el Nuevo Testamento, αἰγιαλός se refiere a la franja de tierra donde el mar se encuentra con la costa, un lugar de transición y encuentro. Jesús enseñó a las multitudes desde una barca mientras ellas permanecían de pie en la playa (Mt 13:2), y los pescadores clasificaban allí su captura (Mt 13:48). El Cristo resucitado se apareció en la orilla del mar de Galilea (Jn 21:4). En Hechos, los creyentes se arrodillaron en oración en la playa de Tiro (21:5), y la tripulación del naufragio divisó una bahía desconocida con playa en Malta (27:39-40).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0124', 'spa', 'Egipcio; perteneciente a Egipto o a su pueblo, usado como adjetivo y como sustantivo.', 'Adjetivo que significa «egipcio», empleado en el Nuevo Testamento para describir a personas originarias de Egipto o cosas asociadas con la cultura egipcia. El discurso de Esteban en Hechos lo usa con mayor frecuencia: Moisés fue instruido en toda la sabiduría de los egipcios (Hch 7:22), mató a un opresor egipcio (7:24, 28), y el tribuno romano confunde a Pablo con un notorio insurrecto egipcio (21:38). Hebreos 11:29 recuerda a los egipcios ahogándose en el Mar Rojo. La palabra funciona tanto como adjetivo descriptivo como sustantivo gentilicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0125', 'spa', 'Egipto: la antigua tierra a lo largo del Nilo, referenciada en el NT por la narrativa del Éxodo, la huida de Jesús y su uso tipológico', 'Egipto: la antigua tierra a lo largo del Nilo, referenciada en el NT por la narrativa del Éxodo, la huida de Jesús y su uso tipológico');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0126', 'spa', 'eterno, perpetuo, sin principio ni fin', 'Este adjetivo describe lo que es eterno o perpetuo—lo que existe sin límites temporales. En Romanos 1:20, Pablo declara que el ''poder eterno'' de Dios ha sido claramente visible desde la creación. En Judas 6, describe las ''cadenas eternas'' que atan a los ángeles caídos en oscuridad esperando el juicio. La palabra enfatiza la perpetuidad y atemporalidad, aquello que trasciende los límites temporales. El griego clásico distinguía este término (perpetuo, sin principio ni fin) de aiōnios (duradero por edades, potencialmente con principio). Es la cualidad de los atributos divinos y las realidades últimas que existen fuera del flujo del tiempo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0128', 'spa', 'etíope, persona de la región al sur de Egipto', 'Este sustantivo designa a un etíope—una persona de la región al sur de Egipto conocida por los griegos como el pueblo de ''cara quemada'' debido a su piel oscura. En Hechos 8, aparece dos veces describiendo al eunuco etíope: un oficial de la corte de la reina etíope Candace que estaba leyendo Isaías cuando Felipe lo encontró (8:27). El término lleva significado tanto geográfico como étnico, marcando a este hombre como proveniente del lejano África. Su conversión representa el alcance del evangelio hasta ''los confines de la tierra,'' cumpliendo la comisión de Jesús mientras el mensaje se mueve más allá de las tierras mediterráneas hacia África.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0129', 'spa', 'Sangre — el fluido vital; usada para la expiación sacrificial, la ratificación del pacto, la culpa por derramamiento y la sangre de Cristo.', 'Αἷμα porta una densidad teológica extraordinaria en sus 98 apariciones neotestamentarias. Literalmente designa el fluido rojo que circula por el cuerpo, pero sus usos figurados superan con creces los literales. «Carne y sangre» es un modismo para la naturaleza humana mortal (Mt 16:17; 1 Co 15:50). La sangre derramada significa muerte violenta y la culpa que acarrea (Mt 23:35; 27:25). Centralmente, la sangre es el medio de expiación: la sangre del nuevo pacto derramada por muchos (Mt 26:28), la sangre de Cristo por la cual viene la redención (Ef 1:7; He 9:12-14). Apocalipsis intensifica todos los registros — sangre de mártires, sangre del Cordero, ríos convertidos en sangre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0132', 'spa', 'Eneas, hombre paralítico sanado por Pedro en Lida', 'Eneas fue un hombre paralítico a quien Pedro sanó en Lida, un incidente que llevó a muchos en la región a volverse al Señor. Su nombre aparece dos veces en Hechos 9: Pedro se dirige a él directamente, ''Eneas, Jesucristo te sana'' (9:33), luego la narrativa relata que había estado postrado en cama por ocho años (9:34). El nombre es griego, posiblemente indicando trasfondo judío helenístico o gentil. Su sanidad demuestra el poder apostólico continuando el ministerio de Jesús y sirve como señal que atrae a toda una región a la fe. Él representa a los físicamente quebrantados a quienes el evangelio restaura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0134', 'spa', 'Alabar, loar o dar gracias vocalmente a Dios en adoración; celebrar las obras de Dios con palabras de aclamación.', 'Verbo de adoración gozosa y vocal dirigida exclusivamente a Dios en el Nuevo Testamento. Las huestes celestiales ''alaban a Dios'' en el nacimiento de Cristo (Lc 2:13), y los pastores se marchan ''alabando a Dios'' por lo que han visto (Lc 2:20). Cuando Jesús se acerca a Jerusalén, toda la multitud de discípulos comienza a ''alabar a Dios a gran voz por todas las maravillas que habían presenciado'' (Lc 19:37). En la iglesia primitiva, los creyentes continúan ''alabando a Dios'' como rasgo distintivo de su vida comunitaria (Hch 2:47). Se trata de una celebración vocal consagrada íntegramente a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0136', 'spa', 'alabanza, elogio, aprobación expresada en palabras', 'Este sustantivo poético y algo arcaico denota alabanza o elogio—aprobación expresada en palabras. En Mateo 21:16, Jesús cita el Salmo 8 a los indignados sumos sacerdotes: ''De la boca de los niños y de los que maman has perfeccionado la alabanza.'' En Lucas 18:43, después de que Jesús sana al mendigo ciego, toda la gente ''daba alabanza a Dios.'' La palabra enfatiza la expresión verbal de aprobación y honor, particularmente dirigida hacia Dios. Es la respuesta articulada de asombro y gratitud, el reconocimiento de grandeza expresado en voz alta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0138', 'spa', 'Elegir, escoger, preferir; tomar para sí mismo por decisión deliberada', 'Verbo de selección deliberada entre opciones. Pablo contempla elegir quedarse con vida por el bien de los filipenses frente a su deseo de partir (Fil 1:22). Dios eligió a los creyentes para salvación «desde el principio» (2 Ts 2:13). Moisés eligió sufrir con el pueblo de Dios en lugar de disfrutar los placeres pasajeros del pecado (He 11:25). El término enfatiza la decisión volitiva: sopesar alternativas y seleccionar una de ellas conscientemente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0139', 'spa', 'Secta, partido religioso o escuela de pensamiento; también facción divisiva, herejía — una opinión elegida que divide a la comunidad.', 'Derivado de αἱρέομαι (''elegir''), este sustantivo significaba originalmente una elección o escuela de pensamiento. En Hechos conserva ese sentido relativamente neutro al designar a fariseos, saduceos y primeros cristianos como partidos reconocidos dentro del judaísmo (Hch 5:17; 15:5; 24:5, 14; 26:5; 28:22). Sin embargo, en las epístolas adquiere una connotación marcadamente negativa: ''herejías destructoras'' que un falso maestro introduce subrepticiamente (2 P 2:1) y ''facciones'' enumeradas entre las obras de la carne (Gá 5:20). Pablo señala incluso que las divisiones deben surgir para que los auténticos sean reconocidos (1 Co 11:19). Así, el término abarca desde la designación sociológica neutra hasta la condena doctrinal severa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0142', 'spa', 'Levantar, tomar, cargar o quitar; abarca elevación física, adquisición, porte sostenido y remoción figurada.', 'Uno de los verbos de movimiento más versátiles del Nuevo Testamento, αἴρω cubre todo el arco desde recoger algo del suelo hasta cargarlo sobre los hombros y despojarlo por completo. Jesús ordena al paralítico «toma tu camilla» (Mt 9:6), pero el mismo verbo describe a Dios «quitando» la rama infructuosa (Jn 15:2). El contexto y la voz determinan si el énfasis recae en el movimiento ascendente, el transporte sostenido o la privación. El uso náutico en Hechos 27 y el modismo psicológico de Juan 10:24 revelan cuánto puede estirarse una raíz simple de elevación física.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0146', 'spa', 'codicioso de ganancia deshonesta, que busca sórdidamente el lucro', 'Este adjetivo compuesto describe a quienes buscan ávidamente ganancia deshonesta—persiguiendo lucro por medios vergonzosos o sórdidos. Aparece en las calificaciones de Pablo para líderes de la iglesia: los diáconos no deben ser ''codiciosos de ganancia deshonesta'' (1 Timoteo 3:8), y los ancianos tampoco deben serlo (Tito 1:7). La palabra combina ''vergonzoso'' y ''ganancia,'' enfatizando no meramente el deseo de dinero sino la disposición a perseguirlo por medios impropios. Es el carácter de quien comprometerá su integridad por lucro, quien valora el dinero por encima del honor o la rectitud.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0149', 'spa', 'Vergonzoso, deshonroso, indigno; feo o deforme en apariencia; moralmente reprochable o infamante', 'Esta palabra opera en dos niveles: físico y moral. En Homero podía describir la fealdad de Tersites o la deformidad de un hombre cojo. Pero con mayor frecuencia designa lo vergonzoso o indigno en la conducta: acciones que traen deshonra en lugar de nobleza. Los griegos antiguos lo contrastaban directamente con καλός (bello, noble), convirtiéndolo en el opuesto de lo admirable. El sentido moral predomina: discursos vergonzosos, acciones viles, comportamiento deshonroso. Cuando algo se califica así, no es meramente desagradable, sino una violación de lo recto y honorable. El término aparece frecuentemente en argumentos éticos sobre lo que se debe o no se debe hacer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0150', 'spa', 'vergonzoso, deshonroso, indigno; moralmente indecente o socialmente impropio, que causa deshonra', 'En el griego clásico, αἰσχρός abarca desde la fealdad física hasta la bajeza moral, siempre en oposición a καλός (''noble, bello''). El NT lo restringe al ámbito moral y social: Pablo declara vergonzoso que una mujer se rape el cabello (1 Cor 11:6), vergonzoso que las mujeres hablen en la asamblea (1 Cor 14:35), y afirma que las obras de las tinieblas son demasiado vergonzosas incluso para mencionarlas (Eph 5:12). En Titus 1:11 los falsos maestros persiguen ''ganancias deshonestas''. El término transmite una fuerte censura moral vinculada a la vergüenza pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0152', 'spa', 'Vergüenza, deshonra, ignominia; tanto el estado objetivo de humillación como el sentimiento subjetivo de bochorno.', 'Αἰσχύνη abarca tanto la emoción dolorosa de sentirse avergonzado como la condición objetiva de deshonra. Jesús soportó la cruz ''menospreciando su vergüenza'' (Heb 12:2), mientras que Pablo renunció a ''lo oculto de la vergüenza'' en su ministerio (2 Co 4:2). Filipenses 3:19 advierte sobre aquellos cuya ''gloria está en su vergüenza'', y Judas 1:13 compara a los falsos maestros con olas bravas ''que arrojan la espuma de su propia vergüenza''. El alcance del término va desde la mortificación interior (Lc 14:9, ocupar el último lugar con humillación) hasta la deshonra pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0153', 'spa', 'Avergonzarse, ser humillado; sentir deshonra o vergüenza, frecuentemente en relación con la fe o la conducta.', 'Expresa la fuerza de avergonzarse o ser puesto en vergüenza, ya sea por los propios fracasos o por el juicio ajeno. El administrador deshonesto admite que le daría vergüenza mendigar (Lucas 16:3). Pablo insiste en que no será avergonzado en su proclamación audaz (2 Cor 10:8; Fil 1:20). Pedro exhorta a los creyentes que sufren como cristianos a no avergonzarse (1 Ped 4:16), y Juan alienta a tener confianza para que «no seamos avergonzados ante él en su venida» (1 Juan 2:28). El término αἰσχύνομαι abarca tanto la dimensión personal e interior de la vergüenza como su manifestación pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0154', 'spa', 'Pedir, solicitar (en oración o a personas); en registro más fuerte: exigir, demandar con autoridad o insistencia.', 'El verbo griego αἰτέω abarca todo el espectro del pedir, desde la petición humilde hasta la exigencia enérgica. En su sentido dominante (61 de 70 apariciones en el NT), es el término estándar para solicitar: «Pedid, y se os dará» (Mt 7:7), orar al Padre por las necesidades cotidianas (Mt 6:8) o acercarse a alguien en busca de ayuda (Mt 5:42). Pero un grupo menor de usos (9 ocurrencias) conlleva una fuerza inconfundible: la multitud que exige a Barrabás (Mt 27:20), los de Tiro y Sidón que «solicitan» paz por depender del territorio de Herodes (Hch 12:20) y la madre de Jacobo y Juan que plantea una pretensión audaz ante Jesús (Mt 20:20). El paso de la petición a la exigencia es sutil pero real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0155', 'spa', 'Petición, solicitud, demanda; aquello que se pide de forma concreta', 'Sustantivo que designa solicitudes concretas dirigidas a autoridades o presentadas en oración. Pilato concedió la «demanda» de la multitud de liberar a Barrabás (Lc 23:24). Pablo exhorta a orar con acción de gracias, dando a conocer las «peticiones» a Dios (Fil 4:6). Juan asegura a los creyentes que ya tienen las «peticiones» que le pidieron a Dios (1 Jn 5:15). En el uso clásico incluye postulados lógicos y matemáticos: cosas que se asumen o se solicitan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0156', 'spa', 'Causa, razón o fundamento; en contextos legales, un cargo formal, acusación o motivo de culpa.', 'Causa, razón o fundamento; en contextos legales, un cargo formal, acusación o motivo de culpa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0158', 'spa', 'Culpable, responsable, reo; causa o razón de algo; quien merece reproche o ha cometido una falta', 'Esta palabra identifica a quien o qué es responsable de algo, frecuentemente con un matiz de culpa. En contextos legales señala al acusado o al culpable: los reos de homicidio o quienes han pecado contra otro. Pero también funciona de manera más neutra como término causal: lo que es responsable de que algo suceda. La misma palabra puede describir la causa de la sequedad del aire (causalidad natural) o la causa de la muerte de alguien (culpabilidad moral). El contexto determina si la responsabilidad es neutra (simplemente ser la razón de algo) o cargada de reproche (ser culpable y digno de castigo). El término transita con fluidez entre explicar causas y asignar culpas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0159', 'spa', 'Causa, razón; parte responsable o fuente; usado para culpabilidad legal y para Cristo como autor de la salvación.', 'Designa una causa, razón o agente responsable, abarcando registros legales, morales y teológicos. En la narrativa de la pasión según Lucas, Pilato declara tres veces que no encuentra «causa» (αἴτιον) de culpa en Jesús (Lc 23:4, 14, 22), haciendo de este un término clave en el drama jurídico del juicio. El secretario de Éfeso advierte que la asamblea tumultuosa carece de «causa» legítima para justificarse (Hch 19:40). De manera más notable, Hebreos 5:9 aplica el término a Cristo como «autor/fuente» de la salvación eterna, un salto semántico extraordinario de la culpabilidad forense a la agencia redentora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0160', 'spa', 'repentino, imprevisto, que ocurre sin aviso ni expectativa', 'Este adjetivo describe eventos que ocurren de manera repentina e inesperada, sin aviso previo. En Lucas 21:34, Jesús advierte que el día del juicio vendrá αἰφνίδιος sobre los desprevenidos, como una trampa que se cierra de golpe. Pablo lo usa de manera similar en 1 Tesalonicenses 5:3 para describir la destrucción repentina que vendrá sobre quienes dicen ''paz y seguridad''. La palabra transmite la fuerza de algo que golpea sin advertencia, enfatizando la necesidad de estar constantemente preparados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0161', 'spa', 'cautividad; estado de ser llevado prisionero, o conjunto de cautivos', 'Sustantivo que expresa tanto la condición de cautividad como el conjunto de los cautivos. Efesios 4:8 cita el Salmo 68: Cristo «llevó cautiva la cautividad», ya sea sometiendo a poderes hostiles o liberando a quienes estaban presos. Apocalipsis 13:10 advierte que quien destina a otros a cautividad irá él mismo a cautividad, expresando la justicia retributiva divina. El término evoca los exilios históricos de Israel y sus derrotas militares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0163', 'spa', 'cautivar, llevar cautivo; tomar prisionero de guerra, o figuradamente dominar y controlar', 'Derivado de αἰχμάλωτος (''prisionero de guerra''), este verbo posee fuerza tanto militar como metafórica en el NT. Jesús profetiza que los habitantes de Jerusalén serán ''llevados cautivos entre todas las naciones'' (Lucas 21:24), en sentido literal de deportación militar. Pablo lo emplea figuradamente: el pecado que mora en él ''lo hace cautivo'' (Romanos 7:23), y el ministerio apostólico ''lleva cautivo todo pensamiento'' a la obediencia de Cristo (2 Corintios 10:5). En 2 Timoteo 3:6, los engañadores ''cautivan'' a personas vulnerables. El término abarca desde la captura bélica hasta el dominio espiritual o intelectual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0165', 'spa', 'Edad, era, época; eternidad o perpetuidad; en doxologías, «por los siglos de los siglos»; raramente, el mundo material.', 'Αἰών es uno de los sustantivos con mayor carga teológica del Nuevo Testamento, portador de todo el peso de la escatología bíblica. En su núcleo significa un lapso de tiempo — una era o época — pero los escritores bíblicos lo extienden en ambas direcciones: hacia atrás, a la eternidad pretemporal, y hacia adelante, a las edades venideras sin fin. La célebre fórmula εἰς τοὺς αἰῶνας τῶν αἰώνων («por los siglos de los siglos») apila era sobre era para expresar lo que ningún vocablo finito puede contener. Sin embargo, la misma palabra puede significar simplemente «este siglo presente» (ὁ αἰὼν οὗτος), el orden actual marcado por el pecado, contrapuesto al «siglo venidero» (ὁ αἰὼν μέλλων).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0166', 'spa', 'Eterno, perpetuo; relativo a una era sin fin, especialmente de la vida divina, el castigo y las realidades del pacto.', 'Un adjetivo teológico de gran peso aplicado a las realidades más trascendentes del Nuevo Testamento: la vida eterna (Jn 3:16; Mt 19:16), el castigo eterno (Mt 25:46), el pacto eterno (He 13:20) y el Espíritu eterno (He 9:14). Derivado de αἰών («era, siglo»), αἰώνιος describe lo que pertenece o se extiende a lo largo del siglo venidero — una duración que sobrepasa toda medida humana. Las traducciones en las principales familias lingüísticas convergen notablemente: «eterno/eterna» en español, «éternel» en francés, «ewig» en alemán, captando todas el sentido de duración ilimitada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0167', 'spa', 'Impureza, inmundicia — contaminación moral, especialmente inmoralidad sexual y corrupción espiritual. El sustantivo ἀκαθαρσία (akatharsia) denota impu', 'Impureza, inmundicia — contaminación moral, especialmente inmoralidad sexual y corrupción espiritual. El sustantivo ἀκαθαρσία (akatharsia) denota impureza o inmundicia moral, principalmente en el ámbito del pecado sexual y la corrupción espiritual. Pablo lo empareja constantemente con πορνεία (inmoralidad sexual) en los catálogos de vicios (Gá 5:19; Ef 5:3; Col 3:5), y lo contrasta tajantemente con la santificación: ''Dios no nos llamó a la impureza, sino a la santidad'' (1 Ts 4:7). Romanos 1:24 lo vincula con la entrega judicial de la humanidad por parte de Dios a las pasiones degradantes. Aunque el término tiene raíces en la impureza ritual levítica, su uso en el Nuevo Testamento es abrumadoramente ético.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0168', 'spa', 'Inmundo, impuro, contaminado; ceremonialmente impuro o moralmente corrupto; sucio o contaminado', 'Este término abarca la impureza ceremonial, moral y física. En contextos rituales, designa aquello que transgrede las leyes de pureza y queda excluido del ámbito sagrado. En sentido moral, describe la corrupción, la depravación y la vileza interior. En su acepción física, se refiere a la suciedad no limpiada o a impurezas sin filtrar. La Septuaginta y el Nuevo Testamento emplean con especial frecuencia el sentido ceremonial para señalar lo que está religiosamente contaminado, estableciendo un contraste constante entre lo santo y lo profano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0169', 'spa', 'Inmundo, impuro — ritual o moralmente contaminado; se usa especialmente para los espíritus inmundos en los Evangelios y Hechos.', 'Inmundo, impuro — ritual o moralmente contaminado; se usa especialmente para los espíritus inmundos en los Evangelios y Hechos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0172', 'spa', 'sin malicia, inocente, libre de intención maligna o engaño', 'Este adjetivo caracteriza a quienes son moralmente puros y sin malicia. En Romanos 16:18, Pablo advierte que los engañadores buscan a los ἄκακοι—los inocentes y confiados—con palabras suaves. Hebreos 7:26 lo aplica a Cristo como nuestro sumo sacerdote, enfatizando su completa pureza moral y separación de los pecadores. El trasfondo griego clásico incluye los significados de ''sin malicia'' (desconocedor del mal) e ''inofensivo'' (que no hace mal), reflejando una pureza interior que hace vulnerable al engaño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0173', 'spa', 'Espina, zarza espinosa — cualquier planta espinosa o con pinchos; usada literal y figuradamente para obstaculos y juicio. El griego ἄκανθα abarca espi', 'Espina, zarza espinosa — cualquier planta espinosa o con pinchos; usada literal y figuradamente para obstaculos y juicio. El griego ἄκανθα abarca espinas y plantas espinosas en general, desde cardos hasta zarzas. En la ensenanza de Jesus, las espinas ahogan la semilla sembrada entre ellas (Mt 13:7, 22), y no se recogen uvas de los espinos (Mt 7:16; Lc 6:44) — imagenes al instante reconocibles en la agricultura mediterranea y del Cercano Oriente. La corona de espinas (Mt 27:29; Mr 15:17; Jn 19:2, 5) transforma una molestia botanica en simbolo de burla y sufrimiento. La palabra evoca Genesis 3:18, donde las espinas aparecen por primera vez como consecuencia de la Caida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0174', 'spa', 'hecho de espinas, espinoso, construido con ramas de espinos', 'Este adjetivo describe objetos hechos de espinas o ramas espinosas. Ambas apariciones en el Nuevo Testamento se refieren al στέφανος ἀκάνθινος—la corona de espinas—colocada sobre Jesús durante su coronación burlesca antes de la crucifixión (Marcos 15:17; Juan 19:5). La palabra enfatiza la composición material: no simplemente decorada con espinas, sino tejida enteramente de ramas espinosas, probablemente con la intención tanto de burlarse de su supuesta realeza como de infligir dolor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0175', 'spa', 'Infructuoso, estéril; que no produce resultado útil, ya sea literalmente de plantas o figuradamente de personas y obras.', 'Adjetivo que significa ''sin fruto'': estéril, improductivo, infructuoso. Combina el prefijo privativo ἀ- con καρπός (fruto) para describir cualquier cosa que no produce resultados. Jesús lo usa en la parábola del Sembrador, donde las distracciones espinosas hacen que la palabra quede ''sin fruto'' (Mt 13:22; Mr 4:19). Pablo lo aplica a la oración ininteligible donde la mente queda ''sin fruto'' (1 Co 14:14) y a ''las obras infructuosas de las tinieblas'' (Ef 5:11). El español ''sin fruto'' refleja con precisión la morfología griega: literalmente ''sin fruto''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0177', 'spa', 'descubierto, sin velo, sin cubrirse la cabeza', 'Este adjetivo describe el estado de estar sin cubierta, específicamente refiriéndose a la cabeza. Ambas apariciones se encuentran en la discusión de Pablo sobre las cubiertas de la cabeza en la adoración en 1 Corintios 11. En el versículo 5, una mujer que ora o profetiza ἀκατακαλύπτῳ κεφαλῇ (con la cabeza descubierta) deshonra su cabeza. El versículo 13 pregunta si es apropiado que una mujer ore descubierta. El contexto cultural involucra prácticas de velarse y honor, aunque el principio teológico que Pablo extrae de esto permanece debatido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0178', 'spa', 'sin condena, no juzgado ni sentenciado aún, sin condenación legal', 'Este adjetivo legal describe a alguien que no ha sido formalmente condenado o sentenciado. Pablo lo usa dos veces al afirmar sus derechos de ciudadanía romana: en Hechos 16:37, después de ser golpeado y encarcelado sin juicio en Filipos, y en Hechos 22:25, cuando estaba a punto de ser azotado en Jerusalén. El término enfatiza la violación del debido proceso—los ciudadanos romanos tenían el derecho de no ser castigados antes de una condena formal. La invocación de Pablo de este estatus destaca la injusticia de su trato y sus protecciones legales como ciudadano romano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0181', 'spa', 'Desorden, inestabilidad, perturbación; agitación social o cósmica, y el tumulto interior de una comunidad dividida.', 'Describe un estado de desorden, inestabilidad o confusión, que abarca desde la agitación política hasta el caos comunitario. Jesús advierte que «guerras y disturbios» precederán al fin (Lc 21:9). Pablo soportó «tumultos» entre sus muchas tribulaciones (2 Cor 6:5) y temía encontrar «desorden» en Corinto (2 Cor 12:20). El pasaje teológicamente más relevante es 1 Corintios 14:33: «Dios no es Dios de desorden sino de paz», estableciendo el orden divino como antítesis de ἀκαταστασία. Santiago 3:16 lo vincula con la envidia y la ambición egoísta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0182', 'spa', 'inestable, inquieto, falto de firmeza o constancia', 'Este adjetivo caracteriza la inestabilidad y la falta de constancia. Santiago lo aplica al hombre de doble ánimo en 1:8, cuya vacilación entre Dios y el mundo lo hace inestable en todos sus caminos. En 3:8, la lengua es llamada ἀκατάστατον κακόν—un mal inquieto, lleno de veneno mortal. El trasfondo clásico incluye situaciones inestables, fiebres irregulares y personas inconstantes. Santiago aprovecha este rango semántico para describir tanto la inestabilidad personal (fe vacilante) como la rebeldía inherente (la lengua indomable).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0183', 'spa', 'Desenfrenado, incontrolable; imposible de contener o refrenar', 'Este raro adjetivo describe algo o a alguien que no puede ser contenido, frenado ni refrenado. El término combina el prefijo negativo con el verbo ''sujetar'' o ''contener'', creando una imagen vívida de fuerza irresistible o impulso incontrolable. En el uso clásico podía describir tanto fuerzas impersonales —como un ímpetu imparable— como características personales de alguien indomable. La palabra conlleva connotaciones de algo salvaje, indómito o fuera del alcance de toda restricción, ya sea una fuerza de la naturaleza o una pasión humana que rompe toda barrera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0185', 'spa', 'puro, sin mezcla, inocente; moralmente íntegro o sin doblez', 'Adjetivo que expresa pureza sin mezcla ni malicia. Jesús instruye a sus discípulos a ser «sencillos como palomas» pero «prudentes como serpientes» (Mt 10:16). Pablo exhorta a los creyentes de Roma a ser «inocentes» respecto al mal (Ro 16:19). Filipenses 2:15 llama a los creyentes a ser «irreprensibles y sencillos», hijos de Dios en medio de una generación corrupta. En el uso clásico abarca sustancias sin mezcla, bienes intactos y personas de carácter íntegro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0189', 'spa', 'Oído (el acto o la facultad de oír); un informe, noticia o mensaje escuchado; el oído como órgano auditivo', 'Oído (el acto o la facultad de oír); un informe, noticia o mensaje escuchado; el oído como órgano auditivo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0190', 'spa', 'Seguir — caminar detrás o acompañar a alguien; especialmente, seguir como discípulo en adhesión comprometida.', 'En los Evangelios, ἀκολουθέω cumple una doble función de extraordinaria relevancia teológica. En la superficie simplemente significa caminar detrás de alguien o acompañarlo — las multitudes que siguen a Jesús por los caminos de Galilea (Mt 4:25). Pero el mismo verbo se convierte en el término definitivo del discipulado cuando Jesús dice «Sígueme» (Mt 9:9; 16:24), transformando una acción espacial en un compromiso de vida. Los discípulos que literalmente dejaron sus redes para caminar detrás de Jesús (Mt 4:20) estaban simultáneamente ingresando en el sentido más profundo de entregar sus vidas a su enseñanza y misión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0191', 'spa', 'Oír, percibir sonido; escuchar, atender, obedecer; en pasiva, ser oído; enterarse por oídas, recibir un informe.', 'Ἀκούω es el verbo griego primario para la experiencia auditiva, con 430 apariciones en todo el Nuevo Testamento, cubriendo el espectro completo desde la percepción física hasta la comprensión espiritual. Su alcance es más amplio que cualquier verbo único del español: cuando Jesús dice «el que tiene oídos, oiga» (Mt 13:9), ἀκούω no significa solo recepción sonora sino comprensión obediente. El español distingue «oír» de «escuchar», y el NT explota teológicamente esta amplitud: «oír» verdaderamente la palabra es recibirla, entenderla y actuar conforme a ella.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0192', 'spa', 'falta de dominio propio, indulgencia desenfrenada, incontinencia moral', 'Este sustantivo denota la ausencia de autodominio o autocontrol, particularmente en apetitos morales y corporales. Jesús lo usa en Mateo 23:25 para acusar a los fariseos de corrupción interior: mientras limpian el exterior de la copa, por dentro están llenos de ἁρπαγῆς καὶ ἀκρασίας—codicia y desenfreno. En 1 Corintios 7:5, Pablo advierte a las parejas casadas que no se priven sexualmente excepto brevemente para la oración, para que Satanás no los tiente διὰ τὴν ἀκρασίαν ὑμῶν—por su falta de dominio propio. El término abarca tanto fracasos éticos como impulsos corporales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0197', 'spa', 'Exacto, preciso, riguroso; de personas: estricto, meticuloso; de acciones: realizado con precisión', 'Este adjetivo describe la exactitud y la precisión en diversos ámbitos. Aplicado a mediciones, tiempos o descripciones, significa preciso o exacto: regresar en el momento justo, una calma total sin perturbación alguna. Referido a personas, caracteriza a quienes son estrictos, meticulosos o perspicaces en sus juicios u observaciones. La forma adverbial aparece con frecuencia en expresiones como ''saber con precisión'' o ''averiguar exactamente'', contrastando con un conocimiento aproximado o superficial de las cosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0198', 'spa', 'averiguar con exactitud, investigar cuidadosamente, determinar con precisión', 'Este verbo significa indagar cuidadosamente o determinar algo con precisión. Ambas apariciones están en la narrativa de la infancia de Mateo concerniente a Herodes y los magos. En 2:7, Herodes llama secretamente a los sabios y ἠκρίβωσεν—averiguó con exactitud—el tiempo en que apareció la estrella. En 2:16, cuando los magos no regresan, Herodes mata a todos los niños en Belén según el tiempo ὃν ἠκρίβωσεν—que había determinado cuidadosamente. El verbo enfatiza la precisión metódica de Herodes al reunir inteligencia para su complot asesino, demostrando trágicamente cómo la investigación cuidadosa puede servir a propósitos malvados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0199', 'spa', 'Con exactitud, cuidadosamente, con precisión; en comparativo: más exactamente, con mayor precisión.', 'Adverbio derivado de ἀκριβής (''exacto, preciso''), que aparece en el Nuevo Testamento tanto en grado positivo como comparativo. En su forma positiva describe una acción cuidadosa y precisa: Herodes indaga secretamente ''con exactitud'' sobre el momento de la estrella (Mt 2:8), Lucas afirma haber investigado todo ''cuidadosamente'' (Lc 1:3), y se exhorta a los creyentes a caminar ''con diligencia'' (Ef 5:15). La forma comparativa (ἀκριβέστερον) aparece en Hechos cuando Priscila y Aquila explican el Camino ''más exactamente'' a Apolos (18:26) y cuando los adversarios buscan información ''más precisa'' sobre Pablo (23:15, 20; 24:22). El español distingue con claridad entre ''exactamente/diligentemente'' y ''más exactamente''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0200', 'spa', 'langosta; insecto que forma plagas, usado como alimento y como imagen apocalíptica del juicio divino', 'La langosta (ἀκρίς) aparece en dos contextos neotestamentarios muy distintos. En los Evangelios forma parte de la dieta de Juan el Bautista en el desierto —''langostas y miel silvestre'' (Mateo 3:4; Marcos 1:6)—, evocando las leyes alimentarias levíticas que permitían ciertos insectos (Levítico 11:22) y simbolizando su estilo de vida profético y austero. En Apocalipsis 9:3, 7, las langostas surgen del abismo como instrumentos del juicio divino, recordando la octava plaga de Éxodo y el ejército de langostas de Joel. El término abarca tanto el sentido literal del insecto como su dimensión apocalíptica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0202', 'spa', 'oidor, oyente; quien escucha un mensaje, especialmente la palabra de Dios, con o sin respuesta obediente', 'En el griego clásico, ἀκροατής designa a quien asiste a una conferencia o discurso público: un ''oyente'' o ''auditor''. El NT convierte este término en una categoría teológica: aquel que oye la palabra de Dios. Pablo contrasta a los oidores con los hacedores de la ley (Romanos 2:13), y Santiago insiste célebremente en que ser ''solamente oidor'' sin actuar conduce al autoengaño (Santiago 1:22-25). El uso neotestamentario cuestiona implícitamente la escucha pasiva y exige una obediencia activa. La tensión inherente del término radica en que oír es necesario pero insuficiente sin la práctica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0203', 'spa', 'Incircuncisión; el estado de tener prepucio y, por metonimia, los incircuncisos como grupo colectivo.', 'Incircuncisión; el estado de tener prepucio y, por metonimia, los incircuncisos como grupo colectivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0204', 'spa', 'piedra angular, piedra fundamental en la esquina que une dos muros', 'Este adjetivo arquitectónico describe la piedra angular—la piedra fundamental colocada en la esquina de un edificio que une dos muros y determina la alineación. Pablo lo usa metafóricamente en Efesios 2:20 donde Cristo es el ἀκρογωνιαῖος—la piedra angular principal—del templo espiritual de Dios, la iglesia. Pedro cita Isaías 28:16 en 1 Pedro 2:6, describiendo a Cristo como la piedra ἀκρογωνιαῖον electa y preciosa puesta en Sion. Ambos apóstoles se basan en imágenes del Antiguo Testamento donde la piedra angular representa lo fundamental, escogido y esencial para la integridad de toda la estructura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0206', 'spa', 'Punto más lejano, extremidad o punta de algo — desde los confines cósmicos del cielo hasta la punta de un dedo (ἄκρον).', 'Sustantivo neutro que designa el punto más lejano o elevado de cualquier extensión, ya sea vasta o diminuta. A escala cósmica, Jesús declara que los ángeles reunirán a los elegidos ''desde un extremo de los cielos hasta el otro'' (Mt 24:31, Mr 13:27). A escala íntima, el hombre rico suplica a Lázaro que moje la ''punta'' de su dedo en agua (Lc 16:24). El español capta bellamente este rango: extremos para las vastas extremidades cósmicas, punta para la precisa punta del dedo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0207', 'spa', 'Aquila (Akylas), fabricante de tiendas judeocristiano originario del Ponto, esposo de Priscila y colaborador del apóstol Pablo.', 'Aquila (en griego Ἀκύλας, del nombre latino que significa ''águila'') fue un creyente judío originario del Ponto, en el norte de Asia Menor. Junto con su esposa Priscila (Prisca), fue expulsado de Roma por el edicto de Claudio y se estableció en Corinto, donde acogió a Pablo y compartió con él el oficio de fabricante de tiendas (Hch 18:2-3). Más tarde, el matrimonio acompañó a Pablo a Éfeso, donde instruyeron a Apolos con mayor precisión en la fe (Hch 18:26). Pablo los menciona constantemente como colaboradores amados (Ro 16:3; 1 Co 16:19; 2 Ti 4:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0208', 'spa', 'anular, invalidar, dejar sin efecto; privar de vigencia legal o autoridad', 'Verbo de anulación jurídica: dejar sin efecto decretos, contratos o enseñanzas. Jesús acusa a los fariseos de «invalidar» la palabra de Dios mediante la tradición (Mt 15:6, Mr 7:13). Pablo argumenta que la ley no puede «anular» el pacto de promesa dado anteriormente a Abraham (Gá 3:17). En el uso clásico incluye la cancelación de decretos y, en sentido figurado, despojar de poder a las pasiones. El término conlleva el peso de una abrogación con plena autoridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0211', 'spa', 'frasco de alabastro; pequeño recipiente sin asas para perfume, típicamente tallado en piedra de alabastro', 'En el mundo mediterráneo antiguo, los perfumes y ungüentos preciosos se guardaban en pequeños frascos globulares tallados en alabastro, un mineral translúcido apreciado por conservar las fragancias. El término griego no designa la piedra en sí, sino el recipiente fabricado con ella. Las cuatro apariciones neotestamentarias describen a una mujer que quiebra uno de estos frascos para ungir a Jesús (Mateo 26:7; Marcos 14:3; Lucas 7:37), un acto de costosa devoción, ya que el cuello sellado debía romperse para liberar el contenido. El gesto subraya la entrega total e irreversible del oferente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0212', 'spa', 'jactancia, pretensión arrogante, ostentación vana', 'Este sustantivo denota jactancia arrogante u ostentación pretenciosa, a menudo acompañada de afirmaciones irreales. Santiago 4:16 condena a aquellos que se jactan en sus ἀλαζονείαις—planes arrogantes—sobre los negocios del mañana, olvidando la fragilidad de la vida y la soberanía de Dios. En 1 Juan 2:16, ἡ ἀλαζονεία τοῦ βίου (la vanagloria de la vida) se enumera junto con la lujuria carnal y la lujuria de los ojos como deseos mundanos que no provienen del Padre. El trasfondo clásico incluye impostura de charlatán y pretensión jactanciosa, sugiriendo no solo orgullo sino autopromoción fraudulenta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0213', 'spa', 'fanfarrón, jactancioso, persona que hace alardes vacíos o arrogantes', 'Este sustantivo describe a una persona caracterizada por la jactancia arrogante o pretensiones vacías. El trasfondo clásico incluye charlatanes ambulantes, sofistas impostores y fanfarrones vacuos. Pablo lo usa en Romanos 1:30 dentro de un catálogo de vicios que describe a la humanidad caída: ἀλαζόνας (jactanciosos) aparece junto a aborrecedores de Dios y los insolentes. En 2 Timoteo 3:2, Pablo advierte que en los últimos días la gente será amante de sí misma, amante del dinero, ἀλαζόνες (jactanciosa) y soberbia. Ambos contextos vinculan la jactancia con otras manifestaciones del orgullo egocéntrico que desprecia a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0214', 'spa', 'dar el grito de guerra, lamentar en voz alta, producir sonidos estruendosos', 'Este verbo originalmente significaba dar el grito de batalla, luego se expandió a los gritos fuertes en ritos orgiásticos, y finalmente a cualquier llanto o lamento fuerte. Marcos 5:38 describe la escena en la casa de Jairo donde la gente estaba ἀλαλάζοντας—lamentando en voz alta—por la niña muerta. En 1 Corintios 13:1, Pablo dice que hablar sin amor lo hace como un gong ruidoso o κύμβαλον ἀλαλάζον—un címbalo que resuena. El rango semántico abarca desde gritos de guerra marciales hasta gritos extáticos rituales, lamentos fúnebres y mero ruido, unidos por la idea de sonido fuerte, a menudo inarticulado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0216', 'spa', 'mudo, sin habla, incapaz de hablar', 'Adjetivo que describe la incapacidad de hablar. Jesús sana a un hombre sordo y «mudo» que luego habló con claridad (Mr 7:37). Un padre trae a su hijo con un «espíritu mudo» que le impide hablar (Mr 9:17), y Jesús ordena al «espíritu mudo y sordo» que salga (9:25). En el uso clásico se aplica a personas que yacen sin habla o que quedan mudas de asombro. Las causas médicas y demoniacas se solapaban en la comprensión antigua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0217', 'spa', 'Sal: la sustancia mineral usada para sazonar, conservar y como metáfora de fidelidad al pacto e influencia moral.', 'El mineral común empleado para dar sabor y conservar alimentos, elevado por Jesús a una de las metáforas más vívidas de los Evangelios. ''Vosotros sois la sal de la tierra'', dice a sus discípulos (Mt 5:13), advirtiendo que la sal que pierde su sabor no sirve para nada. Marcos 9:50 desarrolla la imagen: ''Tened sal en vosotros mismos, y vivid en paz unos con otros.'' Pablo instruye que el hablar debe estar ''sazonado con sal'' (Col 4:6). Detrás de estas metáforas se halla el ''pacto de sal'' veterotestamentario — una alianza inquebrantable. El término designa un solo referente con ricas extensiones metafóricas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0218', 'spa', 'Ungir; frotar o aplicar aceite, ungento o perfume sobre el cuerpo, la cabeza o los pies de una persona por hospitalidad, sanidad o sepultura.', 'A diferencia del verbo chrio, cargado de connotaciones teologicas y mesianicas, aleipho designa el acto cotidiano y fisico de frotar aceite o perfume sobre alguien. Aparece en contextos de aseo personal (Mt 6:17, donde Jesus dice que unjas tu cabeza al ayunar), actos de devocion y hospitalidad (Lc 7:38, 46, donde una mujer unge los pies de Jesus), ministerio de sanidad (Mr 6:13; Stg 5:14, ungir con aceite a los enfermos), y preparacion para la sepultura (Mr 16:1). El termino espanol ''ungir'' conserva bien este sentido concreto y tactil de aplicar una sustancia sobre el cuerpo, distinguiendolo de la consagracion ceremonial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0220', 'spa', 'Gallo; ave domestica cuyo canto marca la vigilia anterior al amanecer, central en el relato de la negacion de Pedro. La palabra griega comun para gall', 'Gallo; ave domestica cuyo canto marca la vigilia anterior al amanecer, central en el relato de la negacion de Pedro. La palabra griega comun para gallo, que aparece exclusivamente en los relatos de la Pasion en los cuatro Evangelios. Jesus profetiza que antes de que cante el gallo, Pedro lo negara tres veces (Mt 26:34; Mr 14:30; Lc 22:34; Jn 13:38), y el canto del gallo se convierte en la devastadora senal de la profecia cumplida (Mt 26:74-75; Mr 14:72; Lc 22:60-61; Jn 18:27). El relato de Marcos especifica de manera unica ''antes de que el gallo cante dos veces''. El canto del gallo funciona asi como algo mas que un marcador temporal: es el sonido de la conciencia y la vindicacion profetica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0221', 'spa', 'alejandrino, nativo o habitante de Alejandría en Egipto', 'Este adjetivo propio identifica a alguien de Alejandría, la gran ciudad helenística de Egipto fundada por Alejandro Magno. Alejandría era un importante centro intelectual y comercial con una gran población judía. Hechos 6:9 menciona miembros de la sinagoga de los alejandrinos (τῶν Ἀλεξανδρέων) que disputaron con Esteban. Hechos 18:24 presenta a Apolos como alejandrino (Ἀλεξανδρεύς) de nacimiento, elocuente y poderoso en las Escrituras. Ambas referencias conectan a los alejandrinos con el aprendizaje y el conocimiento de las Escrituras, reflejando la reputación de la ciudad como centro de erudición judía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0222', 'spa', 'alejandrino, perteneciente a o proveniente de Alejandría', 'Este adjetivo describe cosas que provienen de o están asociadas con Alejandría. Ambas apariciones neotestamentarias se refieren a barcos: en Hechos 27:6, Pablo y sus guardias abordan un barco alejandrino (πλοῖον Ἀλεξανδρῖνον) que navega a Italia. En Hechos 28:11, después de invernar en Malta, navegan en otro barco alejandrino. Estos eran barcos de grano de Egipto, parte de la flota imperial vital que abastecía a Roma con trigo egipcio. La notación de Lucas sobre el origen de los barcos refleja tanto precisión histórica como la importancia del comercio marítimo alejandrino en la economía romana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0223', 'spa', 'Alejandro; nombre personal griego portado por varios personajes del NT, entre ellos un pariente del sumo sacerdote y un herrero.', 'Nombre helenístico común que significa ''defensor de hombres'', llevado por al menos cuatro individuos distintos en el Nuevo Testamento. Alejandro, hijo de Simón de Cirene, es mencionado junto a la cruz (Mr 15:21), lo que sugiere que era conocido por la comunidad de Marcos. Un pariente del sumo sacerdote aparece en Hch 4:6, mientras que un judío es empujado al frente durante el motín en Éfeso (Hch 19:33). Pablo nombra a un Alejandro el herrero que le causó mucho daño (2 Ti 4:14), posiblemente el mismo entregado a Satanás en 1 Ti 1:20. Su retención universal como nombre propio en todas las lenguas refleja su carácter de préstamo léxico consolidado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0224', 'spa', 'harina fina, harina de trigo molida en polvo para hornear', 'Este sustantivo se refiere a harina de trigo finamente molida, el polvo refinado usado para hacer pan. Ambas apariciones están en la parábola de Jesús sobre la levadura: una mujer toma levadura y la esconde en tres medidas de ἀλεύρου (harina) hasta que toda la masa es leudada (Mateo 13:33; Lucas 13:21). La parábola ilustra la influencia penetrante del reino de los cielos—como la levadura obrando a través de toda una masa, el reino transformará el todo. Las tres medidas (unos 40 litros) representan una gran cantidad, suficiente para muchos panes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0225', 'spa', 'Verdad, realidad, fidelidad; la verdad divina, sinceridad y aquello que concuerda con los hechos frente a la falsedad', 'Ἀλήθεια abarca la verdad tanto como cualidad moral como realidad ontológica. En los Sinópticos aparece frecuentemente en expresiones como «en verdad» (ἐπ᾽ ἀληθείας, Mc 12:14), afirmando el habla honesta o la fidelidad divina. En los escritos joánicos adquiere una dimensión marcadamente teológica: Jesús se declara a sí mismo «la verdad» (Jn 14:6) y el Espíritu es llamado «el Espíritu de verdad». Pablo la emplea para referirse al mensaje del evangelio y a la integridad personal. Las traducciones en todas las lenguas principales la vierten con cognados de ''verdad'', lo cual refleja la claridad transcultural del concepto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0226', 'spa', 'hablar la verdad, ser veraz, decir la verdad', 'Este verbo significa hablar o practicar la verdad, enfatizando la comunicación veraz. En Gálatas 4:16, Pablo pregunta retóricamente si se ha convertido en su enemigo por ἀληθεύων—decirles la verdad. Efesios 4:15 exhorta a los creyentes a ἀληθεύοντες ἐν ἀγάπῃ—hablar la verdad en amor—para que puedan crecer hacia Cristo. El uso clásico incluye decir la verdad, probar que las declaraciones son verdaderas y cumplirse (de profecías). Pablo lo emplea para enfatizar un discurso auténtico y veraz que sirve al amor y al crecimiento espiritual en lugar de la adulación o el engaño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0227', 'spa', 'Verdadero, genuino, real: de declaraciones, personas o realidades que no están ocultas y no son falsas', 'Verdadero, genuino, real: de declaraciones, personas o realidades que no están ocultas y no son falsas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0228', 'spa', 'Verdadero, genuino, real: lo que es auténtico y definitivo en contraste con lo que es sombra o falsificación', 'Verdadero, genuino, real: lo que es auténtico y definitivo en contraste con lo que es sombra o falsificación');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0229', 'spa', 'moler, moler grano en harina usando piedras de molino', 'Este verbo significa moler grano, típicamente usando piedras de molino para producir harina. Ambas ocurrencias aparecen en el discurso escatológico de Jesús describiendo actividades diarias interrumpidas por la venida del Hijo del Hombre: dos mujeres estarán ἀλήθουσαι—moliendo en el molino—y una será tomada, la otra dejada (Mateo 24:41; Lucas 17:35). Moler grano era trabajo diario de mujeres en hogares antiguos, usualmente hecho con molinos manuales en la madrugada. Jesús usa esta tarea doméstica ordinaria para ilustrar cómo su regreso vendrá inesperadamente durante actividades normales de la vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0230', 'spa', 'Verdaderamente, ciertamente — adverbio que afirma la realidad o autenticidad de una declaración.', 'Verdaderamente, ciertamente — adverbio que afirma la realidad o autenticidad de una declaración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0231', 'spa', 'Pescador; quien pesca por oficio, asociado especialmente con el mar de Galilea en los Evangelios.', 'Derivado de ἅλς (mar), este sustantivo designa a un pescador profesional. En el Nuevo Testamento aparece exclusivamente en los Evangelios sinópticos para describir a los discípulos galileos a quienes Jesús llamó dejando sus redes. El término porta un peso simbólico considerable: Jesús transforma a estos pescadores en «pescadores de hombres» (Mt 4:19), convirtiendo el humilde oficio en metáfora de la misión apostólica. Las cinco apariciones neotestamentarias se refieren a los discípulos junto al mar de Galilea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0233', 'spa', 'salar, preservar con sal; sazonar o ser salado', 'Verbo que describe la acción o el estado de salar. Jesús advierte que la sal que pierde su sabor no puede volver a «ser salada» (Mt 5:13). Marcos 9:49 afirma que «todos serán salados con fuego», un dicho enigmático que posiblemente alude a pruebas purificadoras. La frase siguiente (también 9:49) habla de sacrificios salados, evocando requisitos levíticos. En el uso clásico incluye sazonar alimentos con sal y formas pasivas para lo que ha sido salado o preservado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0235', 'spa', 'Pero, mas, sino; conjunción adversativa fuerte que marca contraste, objeción o corrección', 'Conjunción adversativa fundamental del griego que introduce un contraste marcado, una objeción o una corrección a lo anteriormente dicho. A diferencia de δέ (que simplemente coordina), ἀλλά señala una oposición enfática o un giro decisivo en el argumento. Se usa para negar una idea previa y afirmar la contraria, o para rectificar un malentendido. Es la conjunción del ''no esto, sino aquello'' que estructura buena parte de la argumentación paulina y de las antítesis del Sermón del Monte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0236', 'spa', 'Cambiar, alterar, intercambiar o transformar; usado tanto del intercambio pecaminoso como de la transformación escatológica.', 'Verbo que abarca todo el espectro desde el intercambio deliberado hasta la transformación divina. Pablo emplea la voz activa de manera impactante en Romanos 1:23, donde la humanidad ''cambió'' (ἤλλαξαν) la gloria de Dios por ídolos, un trueque voluntario y desastroso. En marcado contraste, la voz pasiva aparece en 1 Corintios 15:51-52 para la transformación de los creyentes en la resurrección: ''seremos transformados'' (ἀλλαγησόμεθα). Así, la misma raíz lleva tanto el peor intercambio de la humanidad como el mayor don de Dios. Hechos 6:14 añade la acusación de que Jesús ''cambiaría'' las costumbres mosaicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0237', 'spa', 'de otro lugar, de otra parte, por otra ruta', 'Este adverbio indica origen o dirección desde otro lugar. En Marcos 1:38, Jesús dice a sus discípulos que vayan ἀλλαχοῦ—a los pueblos vecinos—para que pueda predicar allí también. Juan 10:1 lo usa metafóricamente: cualquiera que no entre al redil por la puerta sino que sube ἀλλαχόθεν—por otro lado—es ladrón y salteador. El uso clásico enfatiza origen desde una fuente o ubicación diferente. Marcos lo aplica literalmente al movimiento geográfico, mientras que Juan lo emplea figuradamente para acceso no autorizado, contrastando la entrada legítima (Cristo como puerta) con alternativas ilegítimas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0239', 'spa', 'Aleluya; exclamación litúrgica hebrea que significa ''¡Alabad al SEÑOR!''', 'Esta exclamación hebrea no traducida combina hallel (''alabar'') con Yah (forma abreviada de YHWH), significando literalmente ''¡Alabad al SEÑOR!''. Aparece exclusivamente en Apocalipsis 19:1-6, donde la multitud celestial irrumpe en una cuádruple alabanza tras la caída de Babilonia. Ningún otro libro del NT la emplea, lo cual la convierte en un eco deliberado de los Salmos del Hallel (Salmos 113-118, 146-150) que ahora resuenan en la sala del trono escatológica. Su preservación sin traducir en todos los idiomas refleja su condición de clamor universal de adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0240', 'spa', 'Unos a otros, mutuamente — pronombre recíproco que expresa acción, relación u obligación mutua entre personas', 'Ἀλλήλων es el pronombre recíproco griego, que aparece en genitivo, dativo y acusativo a lo largo de unas 100 ocurrencias en el Nuevo Testamento. Es la columna vertebral gramatical de los mandamientos «unos a otros» que definen la vida comunitaria cristiana: amarse unos a otros (Jn 13:34), sobrellevar las cargas unos de otros (Gá 6:2), perdonarse mutuamente (Ef 4:32), animarse unos a otros (1 Ts 5:11). El pronombre en sí no porta significado independiente —su importancia reside enteramente en los verbos y contextos a los que sirve—, pero se ha convertido casi en una palabra clave teológica, pues la concentración de exhortaciones con ἀλλήλων en las epístolas esboza la forma de la vida mutua en Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0242', 'spa', 'Saltar, brincar, brotar con vigor; movimiento súbito hacia arriba o hacia adelante', 'Verbo que describe un movimiento repentino y vigoroso hacia arriba o hacia adelante. Jesús promete agua viva que será «un manantial que brota» para vida eterna (Juan 4:14). El hombre cojo sanado en la puerta del templo «saltó» y comenzó a caminar alabando a Dios (Hechos 3:8). Cuando Pablo le dijo al paralítico de Listra «¡Ponte derecho!», el hombre «brincó» y caminó (Hechos 14:10). El término transmite un movimiento enérgico e instantáneo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0243', 'spa', 'Otro, diferente; designa una entidad distinta o adicional del mismo tipo, a veces en pares correlativos', 'Uno de los dos vocablos griegos principales para «otro» (junto con ἕτερος), ἄλλος señala un elemento adicional de la misma clase: «otro del mismo tipo». Funciona como adjetivo y pronombre a lo largo de todo el Nuevo Testamento, introduciendo con frecuencia personas, parábolas o eventos adicionales (Mt 2:12; Mc 4:5, 7). En construcciones correlativas como ἄλλος μέν... ἄλλος δέ («uno... otro»), distribuye a los miembros de un grupo, como en Hch 2:12. El español ''otro'', el francés ''autre'' y el alemán ''anderer'' captan todos este matiz de igualdad de clase, sin la connotación de «tipo diferente» que ἕτερος a veces conlleva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0245', 'spa', 'Perteneciente a otro, que no es propio; un extrano o forastero; extranjero, de otra nacion o tierra. El adjetivo griego ἀλλότριος traza una linea firm', 'Perteneciente a otro, que no es propio; un extrano o forastero; extranjero, de otra nacion o tierra. El adjetivo griego ἀλλότριος traza una linea firme entre ''lo mio'' y ''lo que no es mio'', abarcando posesiones, personas y lugares. En su uso mas frecuente describe cosas que pertenecen a otro — el siervo ajeno, el fundamento ajeno, los trabajos ajenos (Ro 14:4; 15:20; 2 Co 10:15-16). Usado sustantivamente, se convierte en ''el extrano'' a quien las ovejas se niegan a seguir en la parabola del pastor (Jn 10:5), y los forasteros contrastados con los ''hijos'' en el dialogo sobre el impuesto del templo (Mt 17:25-26). Ninguna traduccion unica capta perfectamente la capacidad de esta palabra griega de deslizarse desde ''propiedad de otra persona'' hasta ''tierra extranjera'' (Hch 7:6; He 11:9) dentro de la misma raiz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0248', 'spa', 'Trillar el grano; separar los granos de la paja pisoteando o golpeando', 'Verbo que describe el proceso de trilla: bueyes pisando el grano o trabajadores golpeándolo para separar los granos de la paja. Pablo cita Deuteronomio 25:4 dos veces: «No pondrás bozal al buey que trilla» (1 Co 9:9; 1 Ti 5:18), aplicándolo al derecho de sustento de los ministros. En 1 Corintios 9:10 añade que quien trilla debe hacerlo «con esperanza» de participar de la cosecha. La imagen agrícola se convierte en un principio sobre la justa recompensa del trabajo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0249', 'spa', 'Irracional, carente de razón o habla; contrario a la lógica', 'Adjetivo que significa sin λόγος, es decir, sin razón ni habla. Pedro habla de «animales irracionales» que actúan por instinto (2 P 2:12). Judas describe de manera similar a los opositores como criaturas «irracionales» destruidas por su propia corrupción (Judas 10). En Hechos 25:27, Festo lo usa para referirse a lo «irrazonable» de enviar un preso sin especificar los cargos. El uso clásico abarca seres mudos, argumentos ilógicos e instinto bruto opuesto a la razón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0254', 'spa', 'Cadena, grillete — un dispositivo metálico de sujeción para atar prisioneros, usado tanto en sentido literal como simbólico de cautiverio. El sustanti', 'Cadena, grillete — un dispositivo metálico de sujeción para atar prisioneros, usado tanto en sentido literal como simbólico de cautiverio. El sustantivo ἅλυσις (halusis) se refiere a una cadena o grillete utilizado para sujetar a los prisioneros. Su aparición más dramática se encuentra en el relato del endemoniado gadareno, donde el poseído había sido atado con cadenas y grilletes muchas veces, pero los rompía (Mc 5:3-4; Lc 8:29). Pedro duerme en prisión encadenado entre dos soldados antes de que un ángel haga caer las cadenas de sus manos (Hch 12:6-7). Pablo habla de llevar cadenas por el evangelio (Ef 6:20; 2 Ti 1:16), y en Hechos 21:33 y 28:20 es literalmente encadenado por las autoridades romanas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0256', 'spa', 'Alfeo; nombre propio de origen arameo, llevado por dos figuras del NT: el padre de Leví (Mc 2:14) y el padre de Jacobo.', 'Transliteración griega del nombre arameo Chalfay, Alfeo aparece en el Nuevo Testamento como padre de dos discípulos distintos. En Marcos 2:14 se le identifica como padre de Leví, el recaudador de impuestos, mientras que en las cuatro listas apostólicas (Mt 10:3, Mc 3:18, Lc 6:15, Hch 1:13) otro Alfeo figura como padre de Jacobo. Si se trata de una misma persona o de dos ha sido debatido desde la era patrística. La forma genitiva Ἁλφαίου funciona como marca patronímica en todas las apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0257', 'spa', 'era, superficie compacta donde se separa el grano de la paja', 'Este sustantivo denota la era—una superficie dura y plana donde el grano cosechado era trillado y aventado para separar los granos de la paja. Ambas ocurrencias aparecen en la profecía de Juan el Bautista de que el que viene limpiará completamente su ἅλωνα—su era—recogiendo el trigo en el granero pero quemando la paja con fuego inextinguible (Mateo 3:12; Lucas 3:17). La imagen se basa en prácticas de cosecha donde el grano era pisoteado o golpeado, luego aventado, dejando el trigo reunido en un lugar y la paja en otro. Juan usa este proceso agrícola como metáfora del juicio escatológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0258', 'spa', 'Zorra; persona astuta o taimada (en sentido figurado)', 'Sustantivo que designa al animal conocido por su astucia en la tradición antigua. Jesús contrasta su condición de indigencia con la seguridad de los animales salvajes: «Las zorras tienen guaridas… pero el Hijo del Hombre no tiene dónde recostar la cabeza» (Mt 8:20; Lc 9:58). Al ser advertido sobre Herodes Antipas, Jesús lo llama «esa zorra» (Lc 13:32), una referencia punzante a su astucia o insignificancia. En el griego clásico, la imagen de la zorra es proverbial para la trampa y el engaño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0260', 'spa', 'Juntamente, al mismo tiempo; junto con (como preposición que rige dativo). El adverbio ἅμα expresa simultaneidad y unión de dos maneras superpuestas p', 'Juntamente, al mismo tiempo; junto con (como preposición que rige dativo). El adverbio ἅμα expresa simultaneidad y unión de dos maneras superpuestas pero distinguibles. En su uso adverbial primario, significa ''juntamente'' o ''al mismo tiempo'', describiendo una acción concurrente o participación compartida: los creyentes arrebatados ''juntamente'' en las nubes (1 Ts 4:17), la tripulación soltando las anclas ''al mismo tiempo'' (Hch 27:40) y todos ''juntamente'' desviándose (Ro 3:12). En su uso preposicional con dativo, significa ''junto con'' o ''al amanecer'', como en la parábola del trigo y la cizaña —''no sea que al arrancar la cizaña, arranquéis también el trigo junto con ella'' (Mt 13:29)— y el amo de casa que sale ''temprano'' (ἅμα πρωΐ, Mt 20:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0264', 'spa', 'Pecar, errar el blanco, cometer transgresión contra Dios; como participio, el que peca, un pecador.', 'Pecar, errar el blanco, cometer transgresión contra Dios; como participio, el que peca, un pecador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0265', 'spa', 'acto pecaminoso; una acción concreta de transgresión o fallo moral', 'Mientras que el sustantivo más frecuente hamartia (G0266) designa el pecado como condición o principio, este término enfatiza el acto pecaminoso individual: una acción concreta que yerra al blanco. Aristóteles lo situó a medio camino entre la injusticia deliberada y la simple desgracia. En Marcos 3:28-29, Jesús distingue los pecados perdonables de la blasfemia imperdonable contra el Espíritu; en Romanos 3:25, Pablo habla de Dios pasando por alto los pecados cometidos anteriormente; y en 1 Corintios 6:18, el término subraya que la inmoralidad sexual es un pecado cometido contra el propio cuerpo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0266', 'spa', 'Pecado; falta ante la norma de Dios, transgresión moral, errar el blanco de la justicia', 'Derivada de la imagen de un arquero que yerra el blanco, ἁμαρτία se convirtió en el término primordial del Nuevo Testamento para el pecado en todas sus dimensiones: desde actos individuales de desobediencia hasta el poder dominante que esclaviza a la humanidad. En Jn 1:29 el Bautista proclama al Cordero de Dios que quita «el pecado del mundo», mientras que Ro 6:23 declara que su paga es la muerte. La notable uniformidad en las traducciones —''pecado'' (español), ''péché'' (francés), ''Sünde'' (alemán), ''peccato'' (italiano)— refleja cuán central e inequívoco es este concepto en la teología cristiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0268', 'spa', 'ἁμαρτωλός — pecador, pecaminoso; persona caracterizada por el pecado, usado tanto como adjetivo como sustantivo.', 'ἁμαρτωλός — pecador, pecaminoso; persona caracterizada por el pecado, usado tanto como adjetivo como sustantivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0269', 'spa', 'pacífico, no combativo, no contencioso ni pendenciero', 'Este adjetivo describe a alguien que evita pelear o discutir, caracterizado por una disposición pacífica en lugar de contenciosa. El uso clásico incluye significados tanto pasivos (invencible, que no toma parte en batalla) como sentidos activos (imposible de combatir). Pablo lo usa en sus calificaciones pastorales: un supervisor no debe ser dado al vino ni violento sino amable, ἄμαχον—pacífico—no amante del dinero (1 Timoteo 3:3). Tito 3:2 instruye a los creyentes a ser ἀμάχους—pacíficos—amables, mostrando perfecta cortesía a todas las personas. Ambos contextos enfatizan el carácter no combativo como esencial para el liderazgo y testimonio cristiano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0272', 'spa', 'descuidar, desatender; no prestar la debida atención o cuidado a algo importante', 'Derivado del adjetivo ameles (''descuidado''), este verbo describe una falta voluntaria o culpable de atención hacia lo que realmente importa. Su campo semántico abarca desde la indiferencia casual hasta la negligencia espiritual grave. En Mateo 22:5, los invitados simplemente ''no hicieron caso'' de la invitación del rey al banquete, mientras que Hebreos 2:3 eleva la gravedad de forma dramática: ''¿Cómo escaparemos nosotros si descuidamos una salvación tan grande?''. El verbo cubre así desde el descuido cotidiano hasta la desatención de consecuencias eternas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0273', 'spa', 'Irreprensible, sin falta ni reproche; describe a una persona o cosa que está más allá de toda crítica legítima.', 'Compuesto alfa-privativo (a- + memptos, ''censurado''), este adjetivo describe a alguien contra quien no puede sostenerse cargo alguno. Lucas lo aplica a Zacarías y Elisabet, quienes caminaban en todos los mandamientos del Señor (Lc 1:6), mientras que Pablo lo usa tanto de su propia observancia farisaica antes de su conversión (Fil 3:6) como de la aspiración escatológica para los creyentes (1 Ts 3:13). Los equivalentes multilingües —español ''irreprensible'', francés ''irréprochable'', alemán ''untadelig''— convergen en la noción de estar más allá de todo reproche, aunque Hebreos 8:7 aplica el concepto al antiguo pacto mismo y no a personas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0274', 'spa', 'irreprensiblemente, de manera irreprochable, sin motivo de reproche', 'Este adverbio describe una conducta que está más allá de cualquier censura o reproche, realizada de manera irreprochable. Pablo lo usa en 1 Tesalonicenses 2:10 para recordar a sus lectores que Dios y ellos mismos son testigos de cómo ὁσίως καὶ δικαίως καὶ ἀμέμπτως—piadosa, justa e irreprensiblemente—se comportaron los apóstoles entre ellos. En 5:23, Pablo ora para que Dios los preserve completamente, y que su espíritu, alma y cuerpo sean guardados íntegros e irreprensibles (ἀμέμπτως) en la venida de Cristo. El adverbio enfatiza una conducta que resiste el escrutinio, sin dejar motivos para acusación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0275', 'spa', 'libre de preocupación o ansiedad, sin inquietudes, despreocupado', 'Este adjetivo describe el estar libre de cuidados ansiosos o preocupaciones. En Mateo 28:14, a los soldados se les promete que si el gobernador se entera de que se durmieron en la guardia, ''lo persuadiremos y os haremos estar ἀμερίμνους''—os mantendremos libres de preocupación o problemas. Pablo lo usa en 1 Corintios 7:32 para decir que desea que los creyentes estén ἀμερίμνους—libres de ansiedades—contrastando la devoción indivisa posible para los solteros con las preocupaciones divididas de la vida matrimonial. El trasfondo clásico incluye tanto la libertad positiva del cuidado como el descuido pasivo. Pablo emplea el sentido positivo, deseando la libertad de los creyentes para una devoción enfocada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0276', 'spa', 'inmutable, inalterable, que no puede cambiar', 'Este adjetivo describe lo que no puede ser cambiado o alterado. Ambas apariciones se encuentran en Hebreos 6 con respecto a la promesa de Dios a Abraham. El versículo 17 declara que Dios, deseando mostrar a los herederos de la promesa τὸ ἀμετάθετον τῆς βουλῆς αὐτοῦ—el carácter inmutable de su propósito—lo garantizó con un juramento. El versículo 18 habla de dos ἀμετάθετα πράγματα—cosas inmutables—en las cuales es imposible que Dios mienta. El autor construye seguridad sobre la inmutabilidad de Dios: sus propósitos y promesas no pueden cambiar, proporcionando esperanza inquebrantable para los creyentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0278', 'spa', 'irrevocable, sin arrepentimiento, que no se lamenta ni cambia de parecer', 'Este adjetivo describe lo que no está sujeto a arrepentimiento o lamento, por lo tanto irrevocable. Pablo lo usa en Romanos 11:29 para declarar que τὰ χαρίσματα καὶ ἡ κλῆσις τοῦ θεοῦ ἀμεταμέλητα—los dones y el llamamiento de Dios son irrevocables, asegurando el lugar final de Israel en el plan de Dios a pesar de la incredulidad presente. En 2 Corintios 7:10, la tristeza según Dios produce μετάνοιαν εἰς σωτηρίαν ἀμεταμέλητον—arrepentimiento para salvación sin lamento, en contraste con la tristeza mundana que produce muerte. El primer pasaje enfatiza el compromiso inmutable de Dios; el segundo, el valor duradero del verdadero arrepentimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0280', 'spa', 'sin medida, desmesurado, que excede los límites apropiados', 'Este adjetivo describe lo que está sin medida o más allá de los límites. Pablo lo usa dos veces en 2 Corintios 10, discutiendo su esfera apostólica. En el versículo 13, se niega a gloriarse εἰς τὰ ἄμετρα—más allá de los límites, sino que confinará su jactancia a la esfera que Dios le asignó. El versículo 15 igualmente renuncia a gloriarse εἰς τὰ ἄμετρα—sin medida—en los trabajos de otros. El trasfondo clásico incluye inmensidad, exceso moral y desproporción. Pablo lo emplea para describir la extralimitación territorial—reclamar crédito por trabajo en áreas que Dios no le ha asignado—manteniendo límites apropiados en el ministerio apostólico y la jactancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0281', 'spa', 'Amén — afirmación hebrea de verdad y asentimiento; confirma declaraciones, cierra oraciones e introduce (solo en boca de Jesús) proclamaciones solemnes', 'Amén es un préstamo del hebreo que pasó directamente al griego, al latín y a prácticamente todas las lenguas a las que la Biblia ha sido traducida. En el Antiguo Testamento funciona como respuesta congregacional que ratifica juramentos y bendiciones (Dt 27:15-26). El Nuevo Testamento conserva este uso litúrgico al cierre de doxologías y oraciones (Ro 1:25; 1 Co 14:16), pero Jesús introduce un patrón llamativo: «Amén os digo» (Mt 5:18, 26; en Juan el doble «amén, amén»), donde precede en lugar de confirmar, invistiendo sus palabras con autoridad divina. Las 147 ocurrencias comparten el sentido nuclear de afirmación solemne.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0283', 'spa', 'incontaminado, puro; libre de toda contaminación moral o ritual', 'Formado con el prefijo privativo alfa sobre miaino (''manchar, contaminar''), este adjetivo describe lo que permanece completamente libre de contaminación, ya sea moral, ritual o física. En Hebreos 7:26, Cristo como sumo sacerdote es ''santo, inocente, sin mancha''; en Hebreos 13:4 caracteriza el lecho conyugal que debe mantenerse puro. Santiago 1:27 lo aplica a la religión genuina ''sin mancha delante de Dios'', y 1 Pedro 1:4 describe la herencia celestial del creyente como imperecedera e incontaminada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0284', 'spa', 'Aminadab; ancestro de David y de Jesús en la línea mesiánica', 'Nombre hebreo que significa «mi pariente es noble», presente en la genealogía de Jesús. Mateo 1:4 menciona a Aminadab dos veces (en formas nominativa y genitiva) dentro de la línea patriarcal desde Judá, pasando por Ram, hasta Naasón. Lucas 3:33 lo incluye en la genealogía ascendente desde Jesús hasta Adán. Fue padre de Naasón, líder de la tribu de Judá durante el período del desierto (Nm 1:7). Este nombre vincula a Jesús con el liderazgo tribal de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0285', 'spa', 'Arena; material granular fino de costas y desiertos, usado frecuentemente como figura de cantidad innumerable.', 'Sustantivo sencillo que designa la arena como sustancia física, ἄμμος cobra una rica vida figurada en ambos Testamentos. Jesús contrasta edificar sobre la arena con edificar sobre la roca (Mt 7:26), convirtiendo la arena en símbolo de cimiento inestable. Pablo retoma la imagen isaiana de los descendientes de Israel tan numerosos como la arena del mar (Ro 9:27), y Hebreos la emplea igualmente para la descendencia innumerable de Abraham (Heb 11:12). En Apocalipsis, el dragón se para sobre la arena del mar (Ap 12:17). El español ''arena'' y el francés ''sable'' expresan fielmente la sustancia ordinaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0286', 'spa', 'cordero; usado en el NT exclusivamente como título cristológico para Jesús', 'Aunque es la palabra griega común para una oveja joven, cada aparición en el Nuevo Testamento conlleva un peso sacrificial y mesiánico inequívoco. Juan el Bautista identifica dos veces a Jesús como ''el Cordero de Dios'' (Juan 1:29, 36), evocando tanto al cordero pascual como al siervo sufriente de Isaías. Hechos 8:32 cita directamente Isaías 53:7: ''como un cordero ante su trasquilador enmudece'', y 1 Pedro 1:19 habla de la redención mediante ''la sangre preciosa de Cristo, como de un cordero sin defecto''. Este enfoque cristológico constante distingue este término de arnion, el diminutivo ''cordero'' del Apocalipsis.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0288', 'spa', 'Vid, especialmente la vid de uva; usada literalmente de la planta frutal y figuradamente de Cristo como la vid verdadera.', 'Ampelos es la palabra griega comun para la vid, profundamente arraigada en la cultura mediterranea y la imagineria biblica. En los relatos sinopticos de la ultima cena (Mt 26:29; Mr 14:25; Lc 22:18), Jesus habla de no beber mas del ''fruto de la vid'' hasta que llegue el reino, expresion que en espanol se traduce naturalmente como ''vid'' o ''vina''. El uso teologicamente mas rico se encuentra en Jn 15:1-5, donde Jesus declara ''Yo soy la vid verdadera'' y el Padre es el labrador, desarrollando una metafora extensa sobre la permanencia y la fecundidad. En Ap 14:18-19, la vid se emplea escatologicamente para la cosecha del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0290', 'spa', 'Viña: un terreno cultivado de vides, frecuentemente usado en las parábolas de Jesús sobre el reino de Dios', 'Viña: un terreno cultivado de vides, frecuentemente usado en las parábolas de Jesús sobre el reino de Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0294', 'spa', 'vestir, arropar; poner vestiduras sobre alguien', 'Un verbo algo literario y antiguo para vestir o arropar a alguien, usado en el NT exclusivamente por Jesús en dos dichos paralelos sobre el cuidado providencial de Dios. En Mateo 6:30 y Lucas 12:28, Jesús argumenta de menor a mayor: si Dios así viste la hierba del campo, ¡cuánto más vestirá a sus seguidores! Mateo 11:8 y Lucas 7:25 emplean el participio perfecto pasivo para describir a alguien ''vestido con'' ropas finas, contrastando la vestimenta rústica de Juan el Bautista con el lujo de la corte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0297', 'spa', 'Ambos — adjetivo/pronombre que indica dos partes o cosas tomadas juntas como un par. El adjetivo ἀμφότεροι significa ''ambos'', refiriendose a dos entid', 'Ambos — adjetivo/pronombre que indica dos partes o cosas tomadas juntas como un par. El adjetivo ἀμφότεροι significa ''ambos'', refiriendose a dos entidades consideradas juntas como una unidad. En el Nuevo Testamento frecuentemente resalta la union o el destino compartido de elementos o personas emparejados: tanto el vino nuevo como los odres viejos se conservan (Mt 9:17), tanto el trigo como la cizana crecen juntos (Mt 13:30), y tanto los guias ciegos como sus seguidores caen en el hoyo (Mt 15:14). Pablo lo usa teologicamente en Efesios 2:14, 16, 18 para declarar que Cristo ha hecho de ''ambos'' — judio y gentil — uno solo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0299', 'spa', 'Sin mancha, irreprochable, inmaculado: de pureza moral o ritual; tambien (como homografo) amomon, una planta aromatica.', 'Adjetivo que significa ''sin mancha, irreprochable'', tomado del vocabulario sacrificial donde la ofrenda debia ser fisicamente impecable. El Nuevo Testamento lo aplica predominantemente a la pureza moral y espiritual: Cristo presentado como cordero sin mancha (He 9:14; 1 P 1:19), creyentes escogidos para ser santos e irreprochables (Ef 1:4; 5:27; Col 1:22; Fil 2:15; Jud 1:24). El espanol ''sin mancha'' e ''inmaculado'' transmiten con fuerza la limpieza que el termino implica. Una unica aparicion en Ap 18:13 incluye amomon entre articulos de lujo comercial: una planta aromatica (Amomum) que no tiene relacion alguna con el adjetivo moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0300', 'spa', 'Amón, rey de Judá, mencionado en la genealogía de Mateo', 'Nombre propio procedente del hebreo (אָמוֹן) que designa a Amón, rey de Judá. Aparece en el registro genealógico que traza el linaje de Jesús a través de la línea real de David. El nombre figura en el texto recibido de Mateo 1:10, aunque existen variantes textuales para este pasaje. Este rey representa un eslabón en la cadena que conecta la dinastía davídica con el nacimiento del Mesías, cumpliendo así la promesa de un trono eterno para la descendencia de David.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0301', 'spa', 'Amós; nombre de dos figuras en la genealogía de Jesús', 'Nombre propio que aparece en la genealogía de Jesús según Lucas, distinto del profeta Amós. Mateo 1:10 identifica a Amón (variante ortográfica) como rey de Judá, hijo de Manasés. Lucas 3:25 sitúa a Amós en una posición diferente, posiblemente refiriéndose a otro individuo. Las formas hebreas del nombre (אָמוֹן, עָמוֹס) presentan variantes ortográficas en los distintos libros bíblicos. Josefo conserva múltiples formas griegas de estos nombres, reflejando la complejidad textual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0302', 'spa', 'Partícula modal que indica contingencia, indefinición o condiciones hipotéticas; se combina con pronombres relativos, conjunciones y modos verbales', 'Ἄν es una de esas partículas griegas pequeñas que cargan un peso gramatical enorme pero se resisten a la traducción directa en la mayoría de las lenguas modernas. Señala que una afirmación no es simplemente factual sino contingente: dependiente de condiciones, indefinida en alcance o hipotética por naturaleza. Combinada con pronombres relativos crea expresiones universalizadoras como «quienquiera» y «dondequiera»; en oraciones condicionales marca lo que habría sucedido; con verbos en subjuntivo señala posibilidad o propósito. El español frecuentemente absorbe la fuerza de ἄν mediante el modo subjuntivo, mientras que otras lenguas recurren a partículas o reestructuraciones de la cláusula. Su casi invisibilidad en la traducción contradice su centralidad en la lógica modal griega.');